    ///      see `previewDeposit` and `previewMint`.
    function _convertToShares(uint256 assets, Math.Rounding rounding) internal view override returns (uint256) {
        return Math.mulDiv(assets, _feeAdjustedSupply() + 10 ** _decimalsOffset(), totalAssets() + 1, rounding);
    }

    /// @dev Realized-NAV value conversion, net of all fee shares due at this timestamp.
    function _convertToAssets(uint256 shares, Math.Rounding rounding) internal view override returns (uint256) {
        return Math.mulDiv(shares, totalAssets() + 1, _feeAdjustedSupply() + 10 ** _decimalsOffset(), rounding);
    }

    /// @dev Performance-fee NAV assets per one whole sUSDfr token, after removing
    ///      fee-neutral junior-capital credit.
    function _feeExchangeRate(Math.Rounding rounding) private view returns (uint256) {
        return _feeExchangeRateAtSupply(totalSupply(), rounding);
    }

    function _feeExchangeRateAtSupply(uint256 supply, Math.Rounding rounding) private view returns (uint256) {
        return
            Math.mulDiv(10 ** decimals(), _performanceFeeTotalAssets() + 1, supply + 10 ** _decimalsOffset(), rounding);
    }

    function _performanceFeeTotalAssets() private view returns (uint256) {
        return _pricedAssets(3);
    }

    /// @dev Shared linked path retains the existing mark ordering and callback snapshot.
    function _pricedAssets(uint8 kind) private view returns (uint256) {
        return VaultAccrualLib.pricedAssets(asset(), unvestedYield(), address(_storage().impairmentSource), kind);
    }

    /// @dev Computes all parts of a price ratio before opening a delivery/share-operation window.
    function _accrualPricingState() private view returns (IContinuousAccrual.PricingState memory p) {
        SUSDfrStorage storage $ = _storage();
        bool allowed = !$.feeAccrualInProgress && !$.shareUpdateInProgress && $.feeOperationKind == FEE_OPERATION_NONE
            && (!_reentrancyGuardEntered() || VaultAccrualLib.state().materializationRequested);
        return VaultAccrualLib.capture(
            asset(), unvestedYield(), address($.impairmentSource), _feeAdjustedSupply(), allowed
        );
    }

    /// @dev Legacy/off mode preserves its existing callback behavior until governed binding.
    function _beginAccrualPricing() private {
        if (address(VaultAccrualLib.state().reserve) != address(0)) {
            VaultAccrualLib.begin(_accrualPricingState(), totalSupply());
