    }

    /// @dev Converts the stored per-share HWM into the exact asset hurdle consumed by
    ///      `_calculateFees` at `supply`.
    function _highWaterMarkAssets(SUSDfrStorage storage $, uint256 supply) private view returns (uint256) {
