// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.30;

/// @title Config
/// @notice Single source of truth for token naming and protocol default parameters
///         (brief Part 12: names are final but kept in one module so a rebrand is a
///         single change).
library Config {
    // ── Token naming (final per brief Part 12) ──────────────────────────
    string internal constant USDFR_NAME = "Forest Road Dollar";
    string internal constant USDFR_SYMBOL = "USDfr";
    string internal constant SUSDFR_NAME = "Staked Forest Road Dollar";
    string internal constant SUSDFR_SYMBOL = "sUSDfr";
    string internal constant GROVE_NAME = "Forest Road Grove";
    string internal constant GROVE_SYMBOL = "GROVE";
    string internal constant SGROVE_NAME = "Staked Forest Road Grove";
    string internal constant SGROVE_SYMBOL = "sGROVE";

    // ── Collateral class IDs (ADR-0003 as amended: all FIVE live at genesis) ──
    uint256 internal constant CLASS_FILM_TAX_CREDITS = 1;
    uint256 internal constant CLASS_RENEWABLE_ENERGY = 2;
    uint256 internal constant CLASS_LIFE_SCIENCES = 3;
    uint256 internal constant CLASS_REAL_ESTATE = 4;
    /// @dev Marked-to-market, related-party class (ADR-0015) — distinct margin/
    ///      liquidation model, NOT the receivable model of classes 1-4.
    uint256 internal constant CLASS_DIGITAL_ASSETS = 5;
    uint256 internal constant NUM_CLASSES = 5;

    // ── Credit-layer defaults (ADR-0004 / ADR-0014; governance-adjustable) ──
    /// @dev USD amounts in 18 decimals (USDfr units).
    uint256 internal constant DEFAULT_FIRST_LOSS_PER_CLASS = 10_000_000e18;
    uint256 internal constant SGROVE_UNBONDING_PERIOD = 21 days;
    // Reward streaming window (ADR-0021 / audit R4-EC1): notified rewards drip linearly
    // over this period rather than distributing instantly, so rewards accrue in real time
    // (Pendle-compatible) and cannot be sandwiched by a deposit-before-harvest. Governance
    // tunable via setRewardsDuration, bounded by SGROVE_MAX_REWARDS_DURATION.
    uint64 internal constant SGROVE_REWARDS_DURATION = 7 days;
    uint64 internal constant SGROVE_MAX_REWARDS_DURATION = 365 days;

    // ── Governance defaults (ADR-0013/0021; FR-controlled at launch) ─────
    /// @dev Fixed at genesis, minted to the Forest Road treasury (ADR-0013).
    uint256 internal constant GROVE_INITIAL_SUPPLY = 1_000_000_000e18;
    uint48 internal constant GOV_VOTING_DELAY = 1 days;
    /// @dev Fresh Ethereum genesis: owner-approved 2026-09-18; existing proxy settings persist.
    uint32 internal constant GOV_VOTING_PERIOD = 2 days;
    uint256 internal constant GOV_PROPOSAL_THRESHOLD = 1_000_000e18; // 0.1% of supply
    uint256 internal constant GOV_QUORUM_FRACTION = 4; // % of total votes
    uint256 internal constant TIMELOCK_MIN_DELAY = 2 days;
    /// @dev C-01 reserve-loss pre-arm floor. The live arm duration is derived from the
    ///      bound Governor and Timelock at arm time and may be longer; this immutable
    ///      floor prevents a broken or shortened timing dependency from failing open.
    uint256 internal constant RESERVE_LOSS_MIN_PREARM_DURATION = 11 days;
    uint256 internal constant RESERVE_LOSS_SCHEDULING_SLACK = 1 days;
    /// @dev Preserve the original curator pre-arm floor when launch voting is shortened.
    ///      Longer live governance schedules still extend the derived protection.
    uint256 internal constant CURATOR_PRE_ARM_MIN_GOVERNANCE_PATH = 10 days;

    /// @dev Protocol fee on distributed interest (waterfall), in bps. Launch default
    ///      is deliberately modest; governance-adjustable; economic-review item.
    uint256 internal constant DEFAULT_PROTOCOL_FEE_BPS = 1_000; // 10% of interest

    /// @dev AUDIT FIX (SWEEP-2 S2-F1) — PERMANENT HARD CAP ON THE INTEREST PROTOCOL FEE.
    ///      DO NOT DELETE AND DO NOT RAISE WITHOUT FOREST ROAD DIRECTION.
    ///
    ///      Before this, `WaterfallEngine.setProtocolFee` was bounded only by `Config.BPS` — it was
    ///      the ONLY fee rate in the protocol with no permanent ceiling, while its three siblings
    ///      (`setOriginationFee` -> `MAX_ORIGINATION_FEE_BPS`, `sUSDfr.setPerformanceFee` ->
    ///      `MAX_PERFORMANCE_FEE_BPS`, `setManagementFee` -> `MAX_MANAGEMENT_FEE_BPS`) all carry
    ///      one and two of those are PUBLISHED to holders (`maxPerformanceFeeBps()`,
    ///      `maxManagementFeeBps()`) and described here as "permanent in v1". MEASURED: 10,000 bps
    ///      was accepted and took the ENTIRE senior yield leg (`toVault` 0, `toFee` the whole
    ///      interest receipt). Because `_routeInterest` takes this fee FIRST, off the same senior
    ///      income stream the vault's 20% performance cap protects, total capture of senior yield
    ///      was reachable AROUND a cap the protocol advertises as permanent — and the fee recipient
    ///      holds plain USDfr, so it is not a cascade layer.
    ///
    ///      The LEVEL mirrors `MAX_PERFORMANCE_FEE_BPS` (20%), i.e. 2x the launch default, which
    ///      is the house convention for "a permanent ceiling with real governance room under it".
    ///      The level is an economic-review item; the EXISTENCE of the ceiling is not.
    uint16 internal constant MAX_PROTOCOL_FEE_BPS = 2_000; // 20% of interest — permanent in v1

    /// @dev Protocol-level performance fee on sUSDfr NAV gains above the global,
    ///      post-fee high-water mark. Launches at 10% and may only be changed
    ///      prospectively by timelocked governance. The hard cap is permanent in v1.
    uint16 internal constant DEFAULT_PERFORMANCE_FEE_BPS = 1_000; // 10% of profit
    uint16 internal constant MAX_PERFORMANCE_FEE_BPS = 2_000; // 20% of profit

    /// @dev Effective-annual sUSDfr management fee on a 365-day basis. Launches disabled
    ///      and may only be enabled prospectively by timelocked governance. Fractional
    ///      periods use geometric retention; the hard cap is permanent in v1.
    uint16 internal constant DEFAULT_MANAGEMENT_FEE_BPS = 0;
    uint16 internal constant MAX_MANAGEMENT_FEE_BPS = 200; // 2% per 365-day year
    uint64 internal constant MANAGEMENT_FEE_YEAR = 365 days;

    /// @dev Origination fee charged at facility funding, in bps of principal (OID
    ///      mechanics: the borrower nets principal minus fee). Market range for the
    ///      book's verticals is ~1-2% (ADR-0019); per-class governance-adjustable,
    ///      capped at MAX_ORIGINATION_FEE_BPS; economic-review item.
    uint16 internal constant DEFAULT_ORIGINATION_FEE_BPS = 200; // 2% of principal (Forest Road direction)
    uint16 internal constant MAX_ORIGINATION_FEE_BPS = 1_000; // 10% hard cap

    /// @dev Margin-call cure window for marked-to-market classes (ADR-0015:
    ///      "hours-to-days"). Governance-adjustable per class; economic-review item.
    uint64 internal constant DEFAULT_MARGIN_CURE_WINDOW = 1 days;

    // ── Liquidity-layer defaults (ADR-0010/0022; governance-adjustable) ──
    /// @dev Settlement HEARTBEAT (ADR-0022): how often `closeEpoch` may run and refresh
    ///      the liquidity budget. Under the ADR-0022 cooldown model this is NOT the
    ///      holding period — `DEFAULT_REDEEM_COOLDOWN` is. The heartbeat must be SHORT
    ///      relative to the cooldown so the effective wait ≈ cooldown (no compounding).
    ///      Heartbeat/liquidity calibration is an economic-review item (ADR-0022 §X.5).
    uint64 internal constant DEFAULT_EPOCH_DURATION = 1 days;
    /// @dev Share of the treasury's idle canonical-USDC liquidity a settlement may
    ///      distribute to the queue PER
    ///      HEARTBEAT, leaving the remainder for direct USDfr redemptions. Rescaled from
    ///      the legacy 50%/30-day batch to preserve ~50%/30-day throughput at a 1-day
    ///      heartbeat (5000/30 ≈ 167). Economic-review item (ADR-0022 §X.5).
    uint16 internal constant DEFAULT_EPOCH_LIQUIDITY_BPS = 167; // ~1.67%/day ≈ 50%/30d

    /// @dev ADR-0022: forced per-request redemption cooldown. A queued redemption cannot
    ///      settle until `requestedAt + DEFAULT_REDEEM_COOLDOWN`. Matches
    ///      `SGROVE_UNBONDING_PERIOD` (21 days) — long enough that a senior cannot exit
    ///      ahead of a foreseeable loss (front-running / loss-dodge defense).
    uint64 internal constant DEFAULT_REDEEM_COOLDOWN = 21 days;

    /// @dev AUDIT FIX (SWEEP-2 CSG-F2) — the UPPER bound on `RedemptionQueue.setRedeemCooldown`.
    ///      The LOWER bound is `DEFAULT_REDEEM_COOLDOWN` itself and is not a separate constant on
    ///      purpose: the G2W relief ramp in `CollateralRegistry.conservativeSeniorMark` is written
    ///      against that exact constant, so the floor must BE it — a second constant is a second
    ///      thing to forget to move (SEAM-1). 180 days is the same order as
    ///      `SGrove.setUnbondingPeriod`'s `AUDIT FIX (L)` ceiling and exists for the same reason:
    ///      an unbounded setter can permanently freeze every queued senior exit by fat finger.
    uint64 internal constant MAX_REDEEM_COOLDOWN = 180 days;

    /// @dev C-1 anti-dust-wedge floor. Minimum REALIZED value (in USDfr, 18 decimals) a
    ///      redemption request must be worth to enter the queue — $1. `closeEpoch` never burns a
    ///      position worth zero at the conservative mark; it stops there, so a sub-wei "dust" head
    ///      could otherwise wedge the queue for the real positions behind it. Barring dust at entry
    ///      makes that wedge reachable only when the exchange rate has collapsed by >1e18x (a
    ///      >99.9999999999999999% senior loss), at which point every realistically-sized position
    ///      is ALSO worth under a wei and halting the queue is the correct behaviour, not griefing.
    ///      Measured at the REALIZED rate (`convertToAssets`), not the conservative one, so a
    ///      declared-but-unrealized impairment does not lock new exits out of the queue.
    ///      Governance-tunable via `RedemptionQueue.setMinRedemptionValue`.
    uint256 internal constant DEFAULT_MIN_REDEMPTION_VALUE = 1e18; // 1 USDfr ($1)

    // ── Optional senior-yield vesting (ADR-0023; governance-adjustable) ──
    /// @dev Realized senior yield may be vested linearly into `sUSDfr.totalAssets()`
    ///      instead of landing as an instant step. Only ALREADY-REALIZED yield can be
    ///      streamed — nothing forward-looking is ever pre-credited, so ADR-0002
    ///      variable-yield pass-through is untouched. Pendle accepts a valid stepwise SY
    ///      exchange rate; smoothing is an optional market-design control against
    ///      payment-timing games and abrupt asset-denominated price moves, not a Pendle
    ///      protocol prerequisite. Forest Road selected instant recognition for launch.
    ///      Governance may enable a non-zero window prospectively after economic review.
    uint64 internal constant DEFAULT_YIELD_VESTING_PERIOD = 0;
    /// @dev Hard ceiling on a newly opened stream. The vault also stores an absolute stream
    ///      deadline that non-zero governance re-tunes and rollovers may shorten but never
    ///      extend, so alternating settings cannot defer the same realized yield indefinitely.
    uint64 internal constant MAX_YIELD_VESTING_PERIOD = 30 days;

    /// @notice RAMP POSTURE (Forest Road direction, 2026-07-21): concentration limits are
    ///         seeded WIDE OPEN so idle deposit capital can be deployed into originations —
    ///         initially a facility to the digital-assets book — without a concentration
    ///         dimension blocking it before the book has any diversity to measure.
    /// @dev At `BPS` (100%) the admission test `exp > limitBps * base / BPS` reduces to
    ///      `exp > base`, and no single dimension can exceed the book, so NOTHING BINDS.
    ///      Two consequences the operator must hold in mind, both stated rather than implied:
    ///        1. Concentration TELEMETRY GOES DARK. `isOverConcentrated`, the drift events and
    ///           `concentrationHeadroom` all measure against the configured limit, so at 100%
    ///           they report "clean" unconditionally. There is no on-chain early warning while
    ///           this posture holds; monitoring must come from the `ExposureRecorded` stream.
    ///        2. RATCHETING DOWN LATER IS A CLIFF. Limits are ADMISSION control and a standing
    ///           breach is permitted (a decrease can never be blocked, or a risk limit could
    ///           veto a loss being realized). So whatever is concentrated when a real limit is
    ///           set will instantly read as breached and be frozen from further growth until
    ///           the book grows around it. Set the first real limits AT or slightly above the
    ///           actual composition at that time, then step down — do not jump straight to the
    ///           target.
    ///      `Validate.s.sol` prints an unmissable posture block whenever this is in force, so
    ///      an unlimited deployment can never produce output identical to a limited one.
    uint16 internal constant RAMP_CONCENTRATION_LIMIT_BPS = 10_000; // 100% = unbounded

    uint256 internal constant BPS = 10_000;

    /// @notice Forward weight, in bps, that an UNATTESTED permissionless past-due mark
    ///         (`DefaultManager.markPastDue`) carries in the conservative redemption NAV,
    ///         relative to an ATTESTED declared default. Used as the fallback whenever
    ///         `DefaultManager`'s governed slot reads zero (see `pastDueWeightBps()`).
    /// @dev OWNER DECISION (Forest Road, 2026-08-07): "An unattested, permissionless past-due
    ///      mark should NOT carry the same forward weight as an attested declared default."
    ///
    ///      DERIVED, NOT INVENTED. The protocol already governs an evidence ladder — but only on
    ///      the marked-to-market side, where the three rungs are per-class registry parameters:
    ///        - `maxLtvBps`         the rung the protocol is willing to be exposed at (healthy);
    ///        - `marginCallLtvBps`  the rung at which a PERMISSIONLESS, REVERSIBLE early warning
    ///                              fires (`marginCall`) — forward impairment weight ZERO, it only
    ///                              starts a cure clock;
    ///        - `liquidationLtvBps` the terminal rung, where `liquidate` records the FULL
    ///                              outstanding into the impairment pool and `realizeLoss` becomes
    ///                              reachable — forward impairment weight ONE.
    ///      `markPastDue` is the receivable-side analogue of the MARGIN-CALL rung: permissionless,
    ///      reversible, early, and strictly BEFORE the terminal attested rung (`declareDefault`).
    ///      Governance placed that early rung exactly half way along the governed deterioration
    ///      band. From the mainnet-v1 class-5 tuple in `script/Deploy.s.sol`
    ///      (maxLtv 5_000, marginCall 6_500, liquidation 8_000):
    ///
    ///          (marginCallLtvBps - maxLtvBps) / (liquidationLtvBps - maxLtvBps)
    ///            = (6_500 - 5_000) / (8_000 - 5_000) = 1_500 / 3_000 = 1/2 = 5_000 bps.
    ///
    ///      WHY NOT THE ADVANCE RATE ALONE. `maxLtvBps`/`ltvBps` cannot supply this weight, and the
    ///      reasoning is recorded here so it is not re-attempted: the advance rate is DEFINED as the
    ///      break-even recovery on the attested claim face (ClaimBridge documents the denominator as
    ///      `principal * BPS / ltvBps`). Senior loss is `max(0, principal - recovery)`, so at a
    ///      recovery equal to the advance rate the loss is identically ZERO — the advance rate
    ///      derives a weight of 0, which re-opens H-5 and D5-03. Worse, every variant that forces a
    ///      positive number out of it (haircut on face, re-advance against carried principal) is
    ///      MONOTONE THE WRONG WAY: it marks a more conservatively underwritten facility harder.
    ///
    ///      DO NOT set this to zero (re-opens H-5: a conflicted servicer can sit on a declaration
    ///      while seniors exit at par) or to `BPS` (restores the defect this constant fixes).
    ///      `CollateralRegistry.setPastDueWeight` enforces both bounds.
    uint256 internal constant DEFAULT_PAST_DUE_WEIGHT_BPS = 5_000; // 50%

    /// @notice sUSDfr entry guard (audit H-3 residual): the maximum ratio of the STRANDED,
    ///         realized-but-unvested yield stream (`sUSDfr.unvestedYield()`) to the DEPOSIT BASE
    ///         (`sUSDfr.totalAssets()`) that vault entry tolerates before `deposit`/`mint` close as
    ///         degenerate.
    /// @dev THE HAZARD (ADR-0023): the vault physically holds realized yield that vests linearly
    ///      into `totalAssets()` over a window and is EXCLUDED from `totalAssets()` until it does.
    ///      Deposits price on `totalAssets()` (OZ's un-overridden `_convertToShares`), so a
    ///      depositor entering while that stranded stream is large relative to the base buys shares
    ///      cheaply and then skims a pro-rata slice of the stream as it vests — extracting from the
    ///      incumbents who funded it. The hazard scales with `unvestedYield() / totalAssets()`, so
    ///      the guard keys on exactly that ratio.
    ///
    ///      CALIBRATION (economic-review item; audit finding #3 re-key from 10 to 3, then audit
    ///      R16-01). `sUSDfr._capStreamToBase` enforces a retention boundary against the ACTUAL
    ///      staked base on both sides of the vault: after every yield delivery AND before every
    ///      queue outflow, at most `1/(K+1)` of physical vault USDfr remains unvested and any
    ///      excess is recognized immediately. A healthy low-staking vault therefore cannot be
    ///      closed by receiving a payment that is large relative to deposits (FRV-FS-03), nor by
    ///      an ordinary settlement shrinking the base under a live stream (RC-03).
    ///      The guard remains meaningful after a senior write-down, which burns the recognized
    ///      base while leaving an already-live stream physically present.
    ///
    ///      WHY 3 AND NOT 10 (the audit residual). The OLD `K = 10` reopened entry the moment the
    ///      ratio fell to 10 — with the stranded stream still 10/11 (~91%) of the vault balance —
    ///      leaving a near-total skim band `(0, 10]` open. It did NOT "close the entire band": near
    ///      the top of that band a fresh depositor could still skim ~91% of the vault as the stream
    ///      vested. Dropping to `K = 3` collapses the open band to `(0, 3)`. `K = 3` bounds the
    ///      excluded stream at the closure point to 3/4 (~75%) of physical vault assets. It is a
    ///      DIMENSIONLESS ratio, not a wei level, so it holds identically at every vault scale.
    ///
    ///      CORRECTION (AUDIT R16-01, HIGH — the previous justification of the open band was
    ///      FALSE; do not restore it). This comment used to argue that the top of the `(0, K]` band
    ///      is "only reachable while the withheld stream is a MAJORITY of the vault, an
    ///      already-catastrophic near-total-write-down state, never a healthy one". That was wrong,
    ///      and `K` was never what bounded a routine deposit's skim. The FRV-FS-03 inflow leg
    ///      created exactly that ratio in a HEALTHY vault: the cap retained `K/(K+1)` of the
    ///      balance, the largest retention the guard tolerates, which parks the vault at precisely
    ///      `unvestedYield() == K * totalAssets()` — and `_isDegenerate`'s strict `>` left entry
    ///      OPEN on that point. Servicing payments are sized off book principal, not off live
    ///      sUSDfr supply, so any payment large relative to the staked base reached it. What bounds
    ///      the routine skim is the CAP's retention target, now `1/(K+1)`: healthy operation parks
    ///      at ratio `1/K`, a factor of `K^2` inside this guard, with a minority (25%) of the
    ///      vault's cash excluded, and the boundary itself is now CLOSED (`>=`). The band between
    ///      `1/K` and `K` is reachable only through a realized loss or a governance re-pricing of
    ///      the vesting window.
    ///
    ///      Kept a constant rather than a governance-tunable for
    ///      this pass: like `SUSDFR_MAX_SHARE_PRICE_COLLAPSE`, it is a defensive safety floor, not an
    ///      operating knob, and adding storage/setter surface to the namespaced vault struct for it
    ///      is unwarranted complexity here; a future pass may promote it to a governed parameter.
    ///      See `SUSDfr._isDegenerate` and `SUSDfr._capStreamToBase`.
    uint256 internal constant SUSDFR_MAX_STRANDED_YIELD_RATIO = 3;

    /// @dev AUDIT R15-01. Vault entry closes once the realized per-share rate has collapsed to
    ///      below `1 / SUSDFR_DEGENERATE_RATE_DIVISOR` of the stored high-water mark.
    ///
    ///      WHY A SECOND BAND IS NEEDED. `SUSDFR_MAX_STRANDED_YIELD_RATIO` above keys on
    ///      `unvestedYield()`, which is identically zero at the launch instant-recognition policy
    ///      (`DEFAULT_YIELD_VESTING_PERIOD == 0`). That band therefore cannot fire at launch,
    ///      leaving only the `totalAssets() == 0` POINT — and one wei of a permissionless USDfr
    ///      transfer steps off a point. `_isDegenerate`'s own rationale states the hazard is the
    ///      whole neighbourhood, not the point; this restores the neighbourhood at every vesting
    ///      setting.
    ///
    ///      WHY PAR IS THE REFERENCE. The stored high-water mark was tried first and rejected:
    ///      `_accrueFees`'s empty-supply branch ratchets it to `(assets + 1) * 1e18` whenever any
    ///      balance exists while `totalSupply() == 0`, so a pre-seed donation could inflate the
    ///      hurdle arbitrarily and then permanently close entry through this band. That is
    ///      harmless while the HWM only suppresses fees, and becomes a brick the moment entry
    ///      depends on it — the invariant suite caught exactly that. Par is derived from the
    ///      token's own decimals, is scale-free, and no actor can move it.
    ///
    ///      WHY 100. The band must separate a catastrophic collapse from a merely bad year, because
    ///      closing entry is a governance event: a vault below 1% of its high-water mark is the
    ///      near-total write-down the guard exists for, while a 50%-drawdown vault stays open to
    ///      new capital. ECONOMIC-REVIEW ITEM, on the same footing as `K = 3` above — the shape is
    ///      a safety floor, but the exact multiple is a judgement about when recapitalization must
    ///      route through governance rather than through an ordinary deposit.
    uint256 internal constant SUSDFR_DEGENERATE_RATE_DIVISOR = 100;
}

src/interfaces/IsUSDfr.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.30;

import {IERC4626} from "@openzeppelin/contracts/interfaces/IERC4626.sol";

/// @title IsUSDfr
/// @notice The yield-bearing ERC-4626 vault over USDfr (ADR-0005). Yield accrues via the
///         assets/shares exchange rate; exits are routed through the epoch redemption
///         queue (ADR-0010) — the vault's instant withdraw/redeem paths are restricted
///         to the queue module.
interface IsUSDfr is IERC4626 {
    /// @notice Emitted when the redemption queue address is set.
    event RedemptionQueueUpdated(address indexed queue);

    /// @notice Instant exit attempted by an account other than the redemption queue.
    error SUSDfr_QueueOnly();
    /// @notice Share movement involving a sanctioned (blocked) party.
    error SUSDfr_TransferBlocked(address from, address to);
    /// @notice A management-fee rate above the permanent v1 cap was requested.
    error SUSDfr_ManagementFeeTooHigh(uint16 requestedBps);
    /// @notice A performance-fee rate above the permanent v1 cap was requested.
    error SUSDfr_PerformanceFeeTooHigh(uint16 requestedBps);
    /// @notice A fee checkpoint was attempted during a transient share update or
    ///         while a cross-module fee-accounting operation was locked.
    error SUSDfr_FeeAccrualReentrant();
    /// @notice A two-phase fee-accounting operation was completed by the wrong caller
    ///         or with the wrong operation type.
    error SUSDfr_InvalidFeeOperation(address caller, uint8 expectedKind, uint8 actualKind);
    /// @notice Share supply changed during a fee-neutral marked-NAV operation.
    error SUSDfr_FeeOperationSupplyChanged(uint256 expectedSupply, uint256 actualSupply);
    /// @notice A replacement fee recipient was not marked as a protocol-exempt address.
    error SUSDfr_FeeRecipientNotExempt(address recipient);
    /// @notice A proposed impairment source has no code or cannot return a uint256 impairment.
    error SUSDfr_InvalidImpairmentSource(address source);
    /// @notice A source reported less performance-fee impairment than redemption impairment.
    error SUSDfr_InvalidPerformanceFeeImpairment(uint256 pendingImpairment, uint256 performanceImpairment);
    /// @notice Emergency clearing was requested while the current impairment source is valid.
    error SUSDfr_ImpairmentSourceStillReadable(address source);
    /// @notice Emergency clearing was requested when no impairment source is configured.
    error SUSDfr_NoImpairmentSource();
    /// @notice Too little gas was supplied to prove source failure and finish recovery safely.
    error SUSDfr_InsufficientImpairmentRecoveryGas(uint256 available, uint256 required);
    /// @notice Emitted when the (fail-open) points hook reverted on a share move (P-04 telemetry).

    event PointsHookFailed(address indexed from, address indexed to, uint256 value);
    /// @notice Protocol fee shares were minted for time-based management fees.
    event ManagementFeeAccrued(uint256 elapsed, uint256 feeAssets, uint256 feeShares);
    /// @notice Protocol fee shares were minted on marked NAV above the global high-water mark.
    event PerformanceFeeAccrued(
        uint256 oldHighWaterMark, uint256 newHighWaterMark, uint256 profitAssets, uint256 feeAssets, uint256 feeShares
    );
    /// @notice A fee-neutral flow adjusted the global high-water mark.
    event HighWaterMarkAdjusted(uint256 oldHighWaterMark, uint256 newHighWaterMark);
    /// @notice An authorized module checkpointed fees and locked a junior-capacity operation.
    event FeeNeutralMarkedNavChangeStarted(address indexed module, uint256 supply);
    /// @notice The authorized junior-capacity operation released its checkpoint lock.
    event FeeNeutralMarkedNavChangeCompleted(address indexed module, uint256 supply);
    /// @notice The WaterfallEngine locked fee checkpoints before delivering senior yield.
    event YieldNotificationStarted(address indexed module);
    /// @notice Governance cleared a fee-operation lock left behind by a faulty trusted module.
    event FeeOperationEmergencyCleared(address indexed module, uint8 indexed operationKind);
    /// @notice The queue prepared one settlement chunk against the full remaining settlement
    ///         outflow bound before taking any price quote.
    /// @param maxAssets Maximum USDfr that the live settlement can still distribute.
    /// @param projectedHeld Physical USDfr that would remain if that full bound left the vault.
    /// @param instantlyRecognized Previously-unvested yield released before pricing.
    event RedemptionPricingPrepared(uint256 maxAssets, uint256 projectedHeld, uint256 instantlyRecognized);
    /// @notice Timelocked governance changed the prospective annual management-fee rate.
    event ManagementFeeSet(uint16 oldFeeBps, uint16 newFeeBps);
    /// @notice Timelocked governance changed the prospective global performance-fee rate.
    event PerformanceFeeSet(uint16 oldFeeBps, uint16 newFeeBps);
    /// @notice Timelocked governance changed the recipient of future vault fee shares.
    event VaultFeeRecipientSet(address indexed oldRecipient, address indexed newRecipient);
    /// @notice Timelocked governance cleared an unreadable impairment source without checkpointing it.
    /// @dev `failureHash` commits to the failed selector and bounded return evidence, or
    ///      to the semantically invalid pair of impairment values.
    event ImpairmentSourceEmergencyCleared(address indexed source, bytes32 failureHash);

    /// @notice Current fee-net realized exchange rate: assets per one whole sUSDfr token.
    /// @dev Simulates fee shares due at this timestamp even before a checkpoint transaction.
    function currentExchangeRate() external view returns (uint256);

    /// @notice Crystallizes management and global high-water-mark performance fees.
    /// @dev Permissionless. Fee shares mint to `feeRecipient`; no backing assets leave.
    /// @return managementShares Shares minted for the time-based management fee.
    /// @return performanceShares Shares minted for profit above the high-water mark.
    function accrueFees() external returns (uint256 managementShares, uint256 performanceShares);

    /// @notice Prepares queue redemption pricing against the live settlement's full remaining
    ///         outflow bound, then checkpoints fees once against the prepared state.
    /// @dev Queue-only. Using the settlement bound rather than the caller-selected request count
    ///      makes optional-stream recognition independent of keeper chunking (G4/M-2).
    /// @param maxAssets Maximum USDfr the settlement can still distribute.
    /// @return instantlyRecognized Previously-unvested yield released before pricing.
    function prepareRedemptionPricing(uint256 maxAssets) external returns (uint256 instantlyRecognized);

    /// @notice Checkpoints fees and locks checkpoints before an authorized junior-capacity change.
    /// @dev Must be paired atomically with `endFeeNeutralMarkedNavChange` by the same module.
    ///      Junior-capacity effects are excluded by the impairment source's independent
    ///      performance-fee view; this function never infers a capital flow from a NAV re-read.
    function beginFeeNeutralMarkedNavChange() external;

    /// @notice Releases an authorized junior-capacity operation's checkpoint lock.
    /// @dev The caller and share supply must match the opening snapshot.
    function endFeeNeutralMarkedNavChange() external;

    /// @notice Locks vault fee checkpoints before the WaterfallEngine delivers senior yield.
    /// @dev Must be paired atomically with `notifyYield` by the same module.
    function beginYieldNotification() external;

    /// @notice Clears a fee-operation lock that survived a successful trusted-module call.
    /// @dev Timelocked emergency recovery only. Correct module paths open and close their
    ///      lock atomically, so a persistent lock means the trusted caller is faulty.
    function clearStaleFeeOperation() external;

    /// @notice Current global performance-fee rate, in basis points of profit.
    function performanceFeeBps() external view returns (uint16);

    /// @notice Permanent v1 performance-fee ceiling, in basis points.
    function maxPerformanceFeeBps() external pure returns (uint16);

    /// @notice Current annualized management-fee rate, in basis points.
    function managementFeeBps() external view returns (uint16);

    /// @notice Permanent v1 management-fee ceiling, in basis points.
    function maxManagementFeeBps() external pure returns (uint16);

    /// @notice Time basis used to interpret the annual management-fee rate.
    function managementFeeYear() external pure returns (uint64);

    /// @notice Global post-fee high-water mark, in the same units as `feeExchangeRate`.
    function highWaterMark() external view returns (uint256);

    /// @notice Gross rate used for HWM accounting after fee-neutral junior-capital credit.
    /// @dev Unlike `currentExchangeRate`, this does not simulate pending fee shares. It can be
    ///      below the redemption-NAV rate while junior capital protects a live impairment.
    function feeExchangeRate() external view returns (uint256);

    /// @notice Recipient of sUSDfr management/performance fee shares.
    function feeRecipient() external view returns (address);

    /// @notice Last timestamp through which the management fee was accrued.
    function lastFeeAccrual() external view returns (uint64);

    /// @notice Sets the prospective management fee. Timelocked governance only.
    function setManagementFee(uint16 feeBps) external;

    /// @notice Sets the prospective performance fee. Timelocked governance only.
    function setPerformanceFee(uint16 feeBps) external;

    /// @notice Changes the recipient of future vault fee shares. Timelocked governance only.
    function setFeeRecipient(address recipient) external;

    /// @notice Clears a configured impairment source only when a bounded read demonstrably fails.
    /// @dev Timelocked governance recovery path. It deliberately cannot replace a readable source
    ///      or install a new source; normal changes must use the checkpointed setter. Any marked-NAV
    ///      lift is ratcheted fee-free, permanently waiving performance fees embedded in that lift.
    function clearUnreadableImpairmentSource() external;

    /// @notice Sets or clears the conservative marked-NAV impairment source.
    /// @dev Timelocked governance only. A non-zero replacement must pass an ABI read before
    ///      the old valuation period is checkpointed and the replacement is stored.
    function setImpairmentSource(address source) external;

    /// @notice Current conservative marked-NAV impairment source, or zero when unwired.
    function impairmentSource() external view returns (address);

    /// @notice The redemption queue module (sole permitted caller of withdraw/redeem).
    function redemptionQueue() external view returns (address);

    /// @notice Sets the redemption queue. Only DEFAULT_ADMIN_ROLE (timelocked governance).
    function setRedemptionQueue(address queue) external;

    /// @notice Recognizes realized senior yield immediately or starts optional vesting (ADR-0023).
    /// @dev Called by the WaterfallEngine right after it delivers `amount` USDfr into the
    ///      vault. Moves no value. With a zero vesting period, recognition and the resulting
    ///      performance-fee checkpoint complete in the caller's repayment transaction. A
    ///      non-zero governance setting defers recognition linearly as an optional
    ///      market-smoothing policy. Gated by CREDIT_ROLE.
    /// @param amount The realized yield just delivered into the vault.
    function notifyYield(uint256 amount) external;

    /// @notice Realized senior yield not yet released into the exchange rate (ADR-0023).
    function unvestedYield() external view returns (uint256);

    /// @notice The asset base exits price against: realized assets LESS the
    ///         declared-but-unrealized senior impairment (ADR-0022 Option Y).
    /// @dev Always `<= totalAssets()`, so redemption NAV <= deposit NAV.
    function redemptionTotalAssets() external view returns (uint256);

    /// @notice Shares that `assets` buys at the conservative redemption NAV, rounded DOWN.
    /// @dev The floor-rounded counterpart to `previewWithdraw` (which rounds up). The queue caps
    ///      its settlement budget with this so `previewRedeem(result) <= assets` holds by
    ///      construction and settlement can never distribute above the budget (CLAUDE.md §1.3).
    /// @param assets The budget, in USDfr.
    /// @return The largest share count whose conservative redemption value does not exceed `assets`.
    function convertToSharesAtRedemption(uint256 assets) external view returns (uint256);
}

src/libraries/VaultFeeMath.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.30;

import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {FixedPointMathLib} from "solady/utils/FixedPointMathLib.sol";
import {Config} from "./Config.sol";

/// @title VaultFeeMath
/// @notice Existing vault management-fee arithmetic, linked to preserve deployment-size headroom.
/// @dev This is the unchanged fractional-year retention formula from SUSDfr. The vault validates
///      the configured fee bound and computes elapsed time; no financial rule changes here.
library VaultFeeMath {
    /// @notice Original sequential management/performance accounting inputs.
    struct Inputs {
        uint256 supply;
        uint256 markedAssets;
        uint256 performanceMarkedAssets;
        uint256 highWaterMark;
        uint256 elapsed;
        uint256 virtualShares;
        uint256 shareUnit;
        uint16 managementFeeBps;
        uint16 performanceFeeBps;
    }

    /// @notice Asset and share attribution used by the vault's existing fee events.
    struct Calculation {
        uint256 elapsed;
        uint256 managementAssets;
        uint256 managementShares;
        uint256 profitAssets;
        uint256 performanceAssets;
        uint256 performanceShares;
    }

    /// @notice Unchanged sequential fee calculation from SUSDfr, with no external reads.
    /// @dev Management uses redemption NAV. Performance excludes junior-capital credit and
    ///      uses the original-supply hurdle after management dilution. Combined shares ensure
    ///      that fees paid to the same recipient do not dilute one another.
    function calculate(Inputs memory p) public pure returns (Calculation memory calc) {
        calc.elapsed = p.elapsed;
        if (p.supply == 0) return calc;
        uint256 baseEffectiveSupply = p.supply + p.virtualShares;
        if (p.managementFeeBps != 0 && p.elapsed != 0 && p.markedAssets != 0) {
            calc.managementAssets = managementFeeAssets(p.markedAssets, p.managementFeeBps, p.elapsed);
            calc.managementShares = _feeSharesForAssets(calc.managementAssets, p.markedAssets, baseEffectiveSupply);
        }
        if (p.highWaterMark == 0) return calc;
        uint256 supplyAfterManagement = baseEffectiveSupply + calc.managementShares;
        uint256 netPerformanceAssets =
            Math.mulDiv(p.performanceMarkedAssets + 1, baseEffectiveSupply, supplyAfterManagement, Math.Rounding.Floor);
        uint256 hurdleAssets = Math.mulDiv(p.highWaterMark, baseEffectiveSupply, p.shareUnit, Math.Rounding.Ceil);
        if (netPerformanceAssets <= hurdleAssets) return calc;
        calc.profitAssets = netPerformanceAssets - hurdleAssets;
        calc.performanceAssets = Math.mulDiv(calc.profitAssets, p.performanceFeeBps, Config.BPS, Math.Rounding.Floor);
        uint256 totalFeeShares =
            _feeSharesForAssets(calc.managementAssets + calc.performanceAssets, p.markedAssets, baseEffectiveSupply);
        calc.performanceShares = totalFeeShares - calc.managementShares;
    }

    /// @notice Asset-denominated management fee on the conservative AUM base for elapsed seconds.
    /// @dev Raising annual retention to fractional years makes checkpoints frequency neutral,
    ///      apart from the existing fixed-point approximation and integer rounding.
    function managementFeeAssets(uint256 assets, uint16 feeBps, uint256 elapsed) public pure returns (uint256) {
        uint256 wad = 1e18;
        uint256 annualFeeWad = Math.mulDiv(feeBps, wad, Config.BPS, Math.Rounding.Floor);
        uint256 annualRetentionWad = wad - annualFeeWad;
        uint256 elapsedYearsWad = Math.mulDiv(elapsed, wad, Config.MANAGEMENT_FEE_YEAR, Math.Rounding.Floor);
        uint256 retentionWad = uint256(FixedPointMathLib.powWad(int256(annualRetentionWad), int256(elapsedYearsWad)));
        return Math.mulDiv(assets, wad - retentionWad, wad, Math.Rounding.Floor);
    }

    /// @dev Virtual asset/share conversion, rounded down to the configured asset-denominated fee.
    function _feeSharesForAssets(uint256 feeAssets, uint256 markedAssets, uint256 effectiveSupply)
        private
        pure
        returns (uint256)
    {
        return Math.mulDiv(feeAssets, effectiveSupply, markedAssets + 1 - feeAssets, Math.Rounding.Floor);
    }
}

src/libraries/PointsHookGas.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.30;

/// @notice A caller supplied too little gas for a token's configured points hook to complete
///         while retaining enough gas to complete the token epilogue safely.
error PointsHook_InsufficientGas(uint256 available, uint256 required);

/// @title PointsHookGas
/// @notice Shared gas policy for the USDfr and sUSDfr participation-points hooks.
/// @dev A healthy hook may complete at any gas budget above the epilogue reserve. An empty-data
///      failure below the classification threshold is treated as caller-controlled exhaustion
///      and rolls the token movement back. Once that threshold was actually offered, an ordinary
///      module failure remains fail-open and observable. Reserving gas explicitly avoids relying
///      on EIP-150's retained 1/64 to fund catch telemetry and, for sUSDfr, release the
///      share-update lock.
library PointsHookGas {
    /// @dev This is deliberately not an up-front floor: a healthy hook measured at materially
    ///      less gas is allowed to succeed. The classifier covers a cold two-wallet checkpoint
    ///      across at least 128 historical rate epochs with more than 2.6x measured margin.
    uint256 internal constant FAILURE_CLASSIFICATION_GAS = 2_000_000;

    /// @dev Retained by the token rather than offered to the hook, so an exhausted hook can be
    ///      classified and the catch path can emit telemetry or roll the movement back.
    uint256 internal constant POST_HOOK_RESERVE = 30_000;

    /// @notice Returns the maximum gas the caller may offer while retaining its epilogue.
    function hookGasLimit() internal view returns (uint256 hookGas) {
        uint256 available = gasleft();
        if (available <= POST_HOOK_RESERVE) {
            revert PointsHook_InsufficientGas(available, POST_HOOK_RESERVE + 1);
        }
        unchecked {
            hookGas = available - POST_HOOK_RESERVE;
        }
    }

    /// @notice Rolls back an ambiguous empty-data failure below the classification budget.
    /// @dev Callers pass only the returndata size, avoiding an unbounded returndata allocation in
    ///      the token catch path. Non-empty failures and sufficiently funded empty failures remain
    ///      fail-open so a broken optional module cannot freeze financial movements indefinitely.
    function requireSafeFailure(uint256 hookGas, uint256 returnSize) internal pure {
        uint256 supplied;
        unchecked {
            supplied = hookGas + POST_HOOK_RESERVE;
        }
        if (returnSize == 0 && supplied < FAILURE_CLASSIFICATION_GAS) {
            revert PointsHook_InsufficientGas(supplied, FAILURE_CLASSIFICATION_GAS);
        }
    }
}

src/interfaces/IPointsModule.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.30;

/// @title IPointsModule
/// @notice Balance-change hooks consumed by the sUSDfr vault and the USDfr token (ADR-0016,
///         2026-07-14 directive). Both are fail-open at the caller.
interface IPointsModule {
    /// @notice Notifies the points ledger of an sUSDfr share balance change (vault-only).
    function onSharesTransfer(address from, address to, uint256 amount) external;

    /// @notice Notifies the points ledger of a USDfr balance change (USDfr-token-only).
    ///         USDfr holders accrue at a governance multiple of the sUSDfr rate, in lieu of yield.
    function onUSDfrTransfer(address from, address to, uint256 amount) external;

    /// @notice Notifies the points ledger of a curator's new posted first-loss for a class
    ///         (CuratorModule-only). First-loss capital accrues at the curator multiple (P-01).
    /// @param newPosted The curator's live postedOf(classId, curator) after the change.
    function onCuratorStakeChange(address curator, uint256 classId, uint256 newPosted) external;

    /// @notice Notifies the points ledger that a class absorbed a loss (CuratorModule-only).
    ///         Curator positions in that class stop accruing at their cached balance until
    ///         reconciled, so impaired first-loss can't out-accrue live capital.
    /// @dev LEGACY form, retained so an un-upgraded CuratorModule keeps recording the freeze.
    ///      It carries no dilution ratio, so the ledger distrusts every cached balance in the
    ///      class — conservative, never over-crediting. Prefer the three-argument form.
    /// @notice Notifies the points ledger that a class absorbed a loss, with the pool balances
    ///         bracketing the absorption (CuratorModule-only). Equal balances are ignored because
    ///         a representation-only normalization is not an economic loss. For an economic loss,
    ///         the ratio lets the ledger write cached balances down without iterating curators
    ///         (H-03/M-4).
    /// @param classId The collateral class that absorbed the loss.
    /// @param poolBalanceBefore The class first-loss pool balance immediately before absorption.
    /// @param poolBalanceAfter The class first-loss pool balance immediately after absorption.
    function onCuratorLoss(uint256 classId, uint256 poolBalanceBefore, uint256 poolBalanceAfter) external;
}

src/libraries/VaultAccrualLib.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.30;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IContinuousAccrual, IAccrualToken} from "../interfaces/IContinuousAccrual.sol";
import {IImpairmentSource} from "../interfaces/IImpairmentSource.sol";
import {IsUSDfr} from "../interfaces/IsUSDfr.sol";
import {IMintRedeemController} from "../interfaces/IMintRedeemController.sol";

/// @title VaultAccrualLib
/// @notice Linked vault support for virtual assets and coherent callback prices.
/// @dev Runs in the vault's context. The vault retains all role and reentrancy checks.
library VaultAccrualLib {
    /// @custom:storage-location erc7201:forestroad.storage.VaultAccrual
    struct State {
        IContinuousAccrual reserve;
        IContinuousAccrual.PricingState pricing;
        bool cached;
        bool materializationRequested;
        uint256 grossShares;
    }

    bytes32 private constant VAULT_ACCRUAL_STORAGE_LOCATION =
        0x0a3fe45ec0c706c92dec0dc11a11f80ca1f2f84db6d7d4d4986a86500415b200;

    /// @notice Accrual accounting has already been bound to this vault.
    error VaultAccrual_AlreadyBound();
    /// @notice Module identities must describe this same vault and its underlying token.
    error VaultAccrual_WrongModules();
    /// @notice Price-changing operations cannot overlap a callback snapshot.
    error VaultAccrual_OperationInProgress();
    /// @notice The internal price-field selector is outside its defined range.
    error VaultAccrual_InvalidPriceKind();

    /// @notice This vault has bound its permanent continuous accounting source.
    event VaultAccrualBound(address indexed reserve);

    /// @notice Reserve storage within the vault, independent of its historical namespace.
    function state() internal pure returns (State storage $) {
        assembly {
            $.slot := VAULT_ACCRUAL_STORAGE_LOCATION
        }
    }

    /// @notice Validates and binds one reserve after the token's permanent binding.
    /// @dev The host authenticates governance. Both controller and token must identify the same
    ///      reserve before this irreversible binding; malformed fixed-ABI replies fail by name.
    function bind(address reserve, address token) public {
        State storage s = state();
        if (address(s.reserve) != address(0)) revert VaultAccrual_AlreadyBound();
        if (reserve.code.length == 0) revert VaultAccrual_WrongModules();
        (bool ok, bytes memory data) = reserve.staticcall(abi.encodeCall(IContinuousAccrual.accrualModules, ()));
        if (!ok || data.length != 224) revert VaultAccrual_WrongModules();
        uint256[7] memory words = abi.decode(data, (uint256[7]));
        for (uint256 i; i < 7; ++i) {
            if (words[i] > type(uint160).max) revert VaultAccrual_WrongModules();
        }
        IContinuousAccrual.Modules memory m = abi.decode(data, (IContinuousAccrual.Modules));
        if (m.vault != address(this) || m.token != token || m.controller.code.length == 0) {
            revert VaultAccrual_WrongModules();
        }
        (ok, data) = token.staticcall(abi.encodeCall(IAccrualToken.accrualReserve, ()));
        if (!ok || data.length != 32 || abi.decode(data, (uint256)) != uint256(uint160(reserve))) {
            revert VaultAccrual_WrongModules();
        }
        (ok, data) = m.controller.staticcall(abi.encodeCall(IMintRedeemController.modules, ()));
        if (!ok || data.length != 96) revert VaultAccrual_WrongModules();
        uint256[3] memory controllerWords = abi.decode(data, (uint256[3]));
        if (
            controllerWords[0] != uint256(uint160(token)) || controllerWords[1] > type(uint160).max
                || controllerWords[2] != uint256(uint160(reserve))
        ) revert VaultAccrual_WrongModules();
        s.reserve = IContinuousAccrual(reserve);
        emit VaultAccrualBound(reserve);
    }

    /// @notice Reads a local share-operation or reserve-delivery price snapshot.
    /// @param kind Assets=0, entry assets=1, redemption assets=2, performance assets=3, shares=4.
    function cachedPrice(uint8 kind) public view returns (bool active, uint256 value) {
        State storage s = state();
        IContinuousAccrual.PricingState memory p;
        if (s.cached) {
            p = s.pricing;
            active = true;
        } else if (address(s.reserve) != address(0)) {
            IContinuousAccrual.Delivery memory d = s.reserve.accrualDelivery();
            if (d.active) {
                p = d.pricing;
                active = true;
            }
        }
        if (!active) return (false, 0);
        if (kind == 0) value = p.assets;
        else if (kind == 1) value = p.entryAssets;
        else if (kind == 2) value = p.redemptionAssets;
        else if (kind == 3) value = p.performanceAssets;
        else if (kind == 4) value = p.feeAdjustedShares;
        else revert VaultAccrual_InvalidPriceKind();
    }

    /// @notice All vault-owned physical and virtual assets, including an aliased fee recipient.
    function entryAssets(address token) public view returns (uint256 assets) {
        (bool active, uint256 value) = cachedPrice(1);
        if (active) return value;
        assets = IERC20(token).balanceOf(address(this));
        IContinuousAccrual reserve = state().reserve;
        if (address(reserve) != address(0)) {
            IContinuousAccrual.Snapshot memory s = reserve.accrualSnapshot();
            assets += s.seniorUnissued;
            if (s.feeRecipient == address(this)) assets += s.feeUnissued;
        }
    }

    /// @notice Ordinary, redemption or performance assets on the same coherent price snapshot.
    /// @param kind Ordinary assets=0, redemption assets=2, performance assets=3.
    /// @dev Performance removes the full fee-neutral impairment; redemption removes only the
    ///      senior portion. This preserves the original vault's saturating mark arithmetic.
    function pricedAssets(address token, uint256 unvested, address impairment, uint8 kind)
        public
        view
        returns (uint256 assets)
    {
        if (kind != 0 && kind != 2 && kind != 3) revert VaultAccrual_InvalidPriceKind();
        (bool active, uint256 value) = cachedPrice(kind);
        if (active) return value;
        uint256 held = entryAssets(token);
        assets = held > unvested ? held - unvested : 0;
        if (kind == 0 || impairment == address(0)) return assets;
        uint256 mark = IImpairmentSource(impairment).pendingSeniorImpairment();
        if (kind == 3) {
            uint256 performance = IImpairmentSource(impairment).performanceFeeImpairment();
            if (performance < mark) revert IsUSDfr.SUSDfr_InvalidPerformanceFeeImpairment(mark, performance);
            mark = performance;
        }
        return mark >= assets ? 0 : assets - mark;
    }

    /// @notice Refuses stale or overlapping price-changing operations.
    function requireFresh() public view {
        requireIdle();
        IContinuousAccrual reserve = state().reserve;
        if (address(reserve) != address(0)) reserve.requireAccrualFresh();
    }

    /// @notice Rejects an overlapping callback operation without requiring a current loan clock.
    function requireIdle() public view {
        State storage s = state();
        if (s.cached) revert VaultAccrual_OperationInProgress();
        if (address(s.reserve) != address(0) && s.reserve.accrualDelivery().active) {
            revert VaultAccrual_OperationInProgress();
        }
    }

    /// @notice Whether public capacity views can advertise a current executable price.
    function available() public view returns (bool) {
        State storage s = state();
        if (s.cached) return false;
        if (address(s.reserve) == address(0)) return true;
        try s.reserve.requireAccrualFresh() {
            return !s.reserve.accrualDelivery().active;
        } catch {
            return false;
        }
    }

    /// @notice Gross share supply for the fee-rate view, separate from pending fee-adjusted shares.
    /// @dev Reserve token delivery leaves vault supply unchanged. A local share operation must
    ///      retain its complete pre-flow supply, or its projected post-fee-mint supply.
    function feeSupply(uint256 currentSupply) internal view returns (uint256) {
        State storage s = state();
        return s.cached ? s.grossShares : currentSupply;
    }

    /// @notice Captures all pricing bases in one linked call, preserving the source's two marks.
    /// @dev A bound vault has no unvested yield. The explicit input also keeps the public view
    ///      correct before binding. During a snapshot every price stays at that snapshot, and
    ///      another materialization is refused. A source's full admission gate governs readiness.
    function capture(address token, uint256 unvested, address impairment, uint256 shares, bool allowed)
        public
        view
        returns (IContinuousAccrual.PricingState memory p)
    {
        State storage s = state();
        if (s.cached) {
            p = s.pricing;
        } else if (address(s.reserve) != address(0) && s.reserve.accrualDelivery().active) {
            p = s.reserve.accrualDelivery().pricing;
        } else {
            p.entryAssets = entryAssets(token);
            p.assets = p.entryAssets > unvested ? p.entryAssets - unvested : 0;
            p.redemptionAssets = p.assets;
            p.performanceAssets = p.assets;
            if (impairment != address(0)) {
                uint256 senior = IImpairmentSource(impairment).pendingSeniorImpairment();
                uint256 performance = IImpairmentSource(impairment).performanceFeeImpairment();
                if (performance < senior) revert IsUSDfr.SUSDfr_InvalidPerformanceFeeImpairment(senior, performance);
                p.redemptionAssets = senior >= p.assets ? 0 : p.assets - senior;
                p.performanceAssets = performance >= p.assets ? 0 : p.assets - performance;
            }
            p.feeAdjustedShares = shares;
        }
        p.materializationAllowed = allowed && address(s.reserve) != address(0) && available();
    }

    /// @notice Freezes a complete price ratio around a share/asset accounting operation.
    function begin(IContinuousAccrual.PricingState memory pricing, uint256 grossShares) public {
        State storage s = state();
        if (s.cached) revert VaultAccrual_OperationInProgress();
        s.pricing = pricing;
        s.grossShares = grossShares;
        s.cached = true;
    }

    /// @notice Ends the host's local callback-price snapshot after all balance effects.
    function end() public {
        state().cached = false;
    }

    /// @notice Requests delivery from an already guarded withdrawal, without a vault write callback.
    function materialize() public {
        State storage s = state();
        IContinuousAccrual reserve = s.reserve;
        if (address(reserve) == address(0)) return;
        IContinuousAccrual.Snapshot memory book = reserve.accrualSnapshot();
        uint8 legs = book.feeRecipient == address(this) ? 3 : 1;
        uint256 owned = book.seniorUnissued + (legs == 3 ? book.feeUnissued : 0);
        if (owned == 0) return;
        s.materializationRequested = true;
        reserve.materializeAccrued(legs);
        s.materializationRequested = false;
    }

    /// @notice Validates both historical impairment-source selectors before governed wiring.
    /// @dev The bounded first-word probe and ordering check are unchanged from SUSDfr.
    function validateImpairmentSource(address source) public view {
        if (source == address(0)) return;
        (bool readable,) = _probeImpairmentSource(source, gasleft());
        if (!readable) revert IsUSDfr.SUSDfr_InvalidImpairmentSource(source);
    }

    /// @notice Proves a failed impairment read before the host may clear its current source.
    /// @dev Each selector receives 1,000,000 gas, including cold reads through the native
    ///      accrual and assessment dependency closure. Check inside the linked frame so
    ///      delegation cannot consume the allowance. The extra 150,000 covers call overhead,
    ///      EIP-150 forwarding and return to the host even if both probes exhaust their caps.
    ///      Future changes to an admitted source must retain the fresh-read regression margin.
    function impairmentRecoveryFailure(address source) public view returns (bytes32 failureHash) {
        if (source == address(0)) revert IsUSDfr.SUSDfr_NoImpairmentSource();
        uint256 availableGas = gasleft();
        uint256 requiredGas = 2_150_000;
        if (availableGas < requiredGas) {
            revert IsUSDfr.SUSDfr_InsufficientImpairmentRecoveryGas(availableGas, requiredGas);
        }
        bool readable;
        (readable, failureHash) = _probeImpairmentSource(source, 1_000_000);
        if (readable) revert IsUSDfr.SUSDfr_ImpairmentSourceStillReadable(source);
    }

    /// @dev Bounded ABI-shape probe; copy only one word to contain return-data bombs.
    function _probeImpairmentSource(address source, uint256 gasLimit)
        private
        view
        returns (bool readable, bytes32 failureHash)
    {
        if (source.code.length == 0) return (false, keccak256(abi.encode(uint256(0), bytes32(0))));
        bytes4 pendingSelector = IImpairmentSource.pendingSeniorImpairment.selector;
        uint256 pendingImpairment;
        (readable, failureHash, pendingImpairment) = _probeUint256(source, pendingSelector, gasLimit);
        if (!readable) return (false, keccak256(abi.encode(pendingSelector, failureHash)));
        bytes4 performanceSelector = IImpairmentSource.performanceFeeImpairment.selector;
        uint256 performanceImpairment;
        (readable, failureHash, performanceImpairment) = _probeUint256(source, performanceSelector, gasLimit);
        if (!readable) return (false, keccak256(abi.encode(performanceSelector, failureHash)));
        if (performanceImpairment < pendingImpairment) {
            return (
                false,
                keccak256(
                    abi.encode(
                        IsUSDfr.SUSDfr_InvalidPerformanceFeeImpairment.selector,
                        pendingImpairment,
                        performanceImpairment
                    )
                )
            );
        }
    }

    function _probeUint256(address source, bytes4 selector, uint256 gasLimit)
        private
        view
        returns (bool readable, bytes32 failureHash, uint256 value)
    {
        bytes memory callData = abi.encodeWithSelector(selector);
        assembly ("memory-safe") {
            mstore(0x00, 0)
            let success := staticcall(gasLimit, source, add(callData, 0x20), mload(callData), 0x00, 0x20)
            let returnSize := returndatasize()
            readable := and(success, iszero(lt(returnSize, 0x20)))
            value := mload(0x00)
            if iszero(readable) {
                mstore(0x00, returnSize)
                mstore(0x20, value)
                failureHash := keccak256(0x00, 0x40)
            }
        }
    }
}

src/interfaces/IImpairmentSource.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.30;

/// @title IImpairmentSource — declared-but-unrealized senior impairment (ADR-0022 Option Y)
/// @notice The minimal surface the senior vault needs to price redemptions conservatively
///         and keep junior-capital changes out of performance-fee profit. Deliberately narrow:
///         the token layer must not depend on the whole credit layer, and a future implementation
///         (a governance-set manual mark or an aggregator over several credit books) can satisfy
///         this without being a DefaultManager.
/// @dev `pendingSeniorImpairment` is the senior (`sUSDfr`) principal impaired AFTER the junior
///      cascade layers absorb in strict order. `performanceFeeImpairment` removes any temporary
///      uplift supplied by those junior layers from the performance-fee base. See ADR-0022 §Y
///      and ADR-0031.
interface IImpairmentSource {
    /// @notice Senior principal impaired by declared-but-unrealized defaults, net of junior capacity.
    /// @return The impairment in USDfr (18 decimals); zero when the junior layers fully cover.
    function pendingSeniorImpairment() external view returns (uint256);

    /// @notice Impairment deducted when measuring protocol-level performance-fee profit.
    /// @dev Must be greater than or equal to `pendingSeniorImpairment()`. The difference is
    ///      fee-neutral junior-capital or valuation credit: it can improve redemption protection
    ///      but cannot itself be charged as senior investment performance. A professional
    ///      assessment may snapshot a lower value that recognizes supported recovery while
    ///      preserving the junior-capital credit standing when that assessment was published.
    /// @return The performance-fee impairment in USDfr (18 decimals).
    function performanceFeeImpairment() external view returns (uint256);
}

src/interfaces/IContinuousAccrual.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.30;

/// @title IContinuousAccrual
/// @notice Reserve-owned accounting and exact delivery of previously accrued interest.
/// @dev Separate from the legacy reserve interface so activation is explicit. Amounts are
///      normalized to 18 decimals. Delivery changes physical balances, never economic ownership.
interface IContinuousAccrual {
    /// @notice Modules bound to one independently backed chain instance.
    /// @dev LAYOUT-FROZEN: embedded or array storage; changing its width shifts later live fields.
    struct Modules {
        address token;
        address controller;
        address vault;
        address waterfall;
        address bridge;
        address registry;
        address defaultManager;
    }

    /// @notice Constant-time accounting, capped at the first unprocessed schedule boundary.
    /// @dev LAYOUT-FROZEN: embedded or array storage; changing its width shifts later live fields.
    struct Snapshot {
        uint256 gross;
        uint256 unposted;
        uint256 unissued;
        uint256 seniorUnissued;
        uint256 feeUnissued;
        address feeRecipient;
        uint64 accruedThrough;
        bool enabled;
        bool fresh;
    }

    /// @notice Vault-computed prices and permission for a neutral physical delivery.
    /// @dev entryAssets includes any unvested assets; assets is the ordinary share-price base.
    /// @dev LAYOUT-FROZEN: embedded or array storage; changing its width shifts later live fields.
    struct PricingState {
        uint256 assets;
        uint256 entryAssets;
        uint256 redemptionAssets;
        uint256 performanceAssets;
        uint256 feeAdjustedShares;
        bool materializationAllowed;
    }

    /// @notice One immutable, same-transaction permit and coherent public price snapshot.
    /// @dev Unselected amounts are zero. A zero/default inactive record grants no authority.
    /// @dev LAYOUT-FROZEN: embedded or array storage; changing its width shifts later live fields.
    struct Delivery {
        uint256 nonce;
        uint256 senior;
        uint256 fee;
        uint256 effectiveSupply;
        uint256 backing;
        uint256 recognizedBacking;
        PricingState pricing;
        address controller;
        address vault;
        address feeRecipient;
        uint64 accruedThrough;
        uint8 legs;
        bool active;
    }

    /// @notice Reads the configured module identities, including before activation.
    function accrualModules() external view returns (Modules memory);

    /// @notice Reads recognized income and its outstanding physical posting/issuance.
    function accrualSnapshot() external view returns (Snapshot memory);

    /// @notice Reads the current delivery permit, or an inactive default record.
    function accrualDelivery() external view returns (Delivery memory);

    /// @notice Refuses a price-sensitive write at an unresolved accrual boundary or operation.
    function requireAccrualFresh() external view;

    /// @notice Delivers selected existing claims: senior=1, fee=2, both=3.
    /// @dev No amount, destination, timestamp or fee rate is supplied by the caller.
    function materializeAccrued(uint8 legs) external returns (uint256 senior, uint256 fee);
}

/// @notice Token continuation accepting only the bound reserve's current exact permit.
interface IAccrualToken {
    /// @notice The immutable-once-configured accounting reserve, or zero before binding.
    function accrualReserve() external view returns (address);

    /// @notice Mints the selected legs of one unused, active delivery permit.
    function mintAccrued(uint256 nonce) external;
}

/// @notice Controller continuation, callable only by its configured reserve.
interface IAccrualController {
    /// @notice Relays one exact reserve-owned delivery permit to the token.
    function mintAccrued(uint256 nonce) external;
}

/// @notice Vault views needed to admit a neutral delivery without a guarded write callback.
interface IAccrualVault {
    /// @notice The immutable-once-configured accounting reserve, or zero before binding.
    function accrualReserve() external view returns (address);

    /// @notice Supplies a coherent price snapshot and current delivery admission state.
    function accrualPricingState() external view returns (IContinuousAccrual.PricingState memory);
}

src/interfaces/IComplianceRegistry.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.30;

/// @title IComplianceRegistry
/// @notice Compliance capability layer (ADR-0011, as amended by the 2026-07-14 directive):
///         a KYC allowlist consulted ONLY at the mint/redeem primary gate, and a narrow
///         sanctions blocklist consulted on transfers. The per-token transfer-allowlist
///         capability was removed — transfers are permissionless (sanctions-only). Policy
///         (who is eligible/sanctioned) is set by governance/counsel off this interface.
interface IComplianceRegistry {
    /// @notice Emitted when an account's KYC allowlist status changes.
    event AllowlistUpdated(address indexed account, bool allowed);
    /// @notice Emitted when an account's sanctions/jurisdiction-block status changes.
    event JurisdictionBlockUpdated(address indexed account, bool blocked);
    /// @notice Timelocked governance changed an address's borrower-payout approval.
    /// @dev This list is deliberately independent of the operational KYC allowlist.
    event FundingRecipientApprovalUpdated(address indexed account, bool approved);

    /// @notice True if `account` has passed KYC and may use the gated primary paths
    ///         (USDfr mint/redeem). Holding and transferring are permissionless.
    function isAllowed(address account) external view returns (bool);

    /// @notice True if `account` is on the sanctions/jurisdiction blocklist.
    function isJurisdictionBlocked(address account) external view returns (bool);

    /// @notice True only when timelocked governance approved `account` as a borrower-payout
    ///         destination and the account is not currently jurisdiction-blocked.
    function isFundingRecipientAllowed(address account) external view returns (bool);

    /// @notice True for a governance-designated internal protocol module.
    function isProtocolExempt(address module) external view returns (bool);

    /// @notice Transfer gate consulted by protocol tokens on every transfer. Transfers are
    ///         permissionless except for sanctioned (blocked) parties; burns are always
    ///         permitted; protocol modules are never treated as blocked.
    /// @param token Retained for interface stability; no longer affects the result.
    /// @param from Sender (zero on mint).
    /// @param to Recipient (zero on burn).
    /// @return True if the transfer may proceed.
    function canTransfer(address token, address from, address to) external view returns (bool);
}

src/interfaces/IMintRedeemController.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.30;

/// @notice The one-bit pause surface of a wired module, declared here because `previewRedeem` must
///         read the reserve's pause and `IReserveManager` does not declare it.
/// @dev CANTINA 3.1.3 LIMB (a), CLOSED BY CONSTRUCTION ON THIS INSTANCE. On Ethereum the quote read
///      the controller pause and the token pause but not the reserve's, so it could publish a full
///      price for a redemption whose every release is `whenNotPaused`. The disposition there was
///      "an integrator should read `ReserveManager.paused()` alongside the quote", because closing
///      it was an upgrade. The mechanical reason the sibling fix missed the third surface is that
///      `ReserveManager` gets `paused()` from `PausableUpgradeable` and never declares it on its own
///      interface, so nothing in the type system pointed at it. This declaration is that pointer.
interface IPausableModule {
    /// @notice True while the module refuses its `whenNotPaused` entry points.
    function paused() external view returns (bool);
}

/// @title IMintRedeemController
/// @notice KYC-gated issuance and redemption of USDfr against canonical USDC, and the enforcement
///         point of the protocol's solvency rule. MINT is at par and is CLOSED while the protocol
///         is under-backed. REDEMPTION is at par while the protocol is whole; while it is short it
///         settles at the JUNIOR-DRAWN price, which is at least the coverage ratio and MAY BE PAR,
///         and which the caller must elect via `redeem(uint256,uint256)`.
///         AUDIT FIX (SWEEP-2 S2-I1) — THIS FILE-LEVEL LINE SAID "at the coverage ratio while it is
///         short", the THIRD round in which a false settlement claim sat on the one line an
///         explorer or ABI doc renders first. SWEEP-1 MRC-F2 corrected the two `redeem` overloads
///         and the contract-level block and left this headline. Falsified by the shipped
///         `ADR0034Y_AtomicJuniorExitDraw::test_Y_theExitSettlesAtParWhileCuratorCapitalStandsIntact`
///         and by SWEEP-2 S2-F3, in which a sub-par book settled at PAR because ADR-0034 Y-bis drew
///         junior capital forward to fund it.
/// @dev THE SOLVENCY RULE IS NOT ADR-0012's ABSOLUTE PREDICATE ANY MORE, AND THIS HEADLINE USED TO
///      SAY IT WAS (corrected in audit round R18). Until R18 this contract-level notice line read "KYC-gated 1:1
///      mint/redeem … `USDfr.totalSupply() <= backingValue()` after every supply-affecting op".
///      Both halves were false of the shipped code, and an auditor handed ADR-0012 plus this
///      interface as the specification would reasonably have reported "the contract does not
///      enforce its stated invariant" as a High. What the contract actually enforces:
///        - Redemption is NOT 1:1. R16-M3 made the exit price `backing / supply` while short, and
///          R17 gave the one-argument form a PAR FLOOR, so it reverts rather than settling short.
///        - The absolute predicate was REPLACED by the NON-WORSENING rule: an operation may not
///          increase `deficit = max(0, totalSupply - backingValue)`. While the protocol is whole
///          that reduces exactly to ADR-0012 and still reverts with
///          `Controller_BackingInvariantViolated`; while it is short it permits the operations that
///          repair holders' position and refuses the ones that dilute it. See
///          `MintRedeemController`'s contract-level NatSpec, which sets out the whole model.
///        - It is not asserted "after every supply-affecting op": `burnLoss` carries NO solvency
///          assertion, deliberately (finding M6 — the assertion it used to carry was unfalsifiable).
///      The comment was not independently wrong: it correctly quoted `ADR/0012-backing-invariant.md`
///      (Status: Accepted), which still states the superseded absolute rule verbatim as "a hard
///      on-chain check on every supply-affecting operation". THAT ADR MUST BE AMENDED OR SUPERSEDED
///      so the code and the decision record agree; it is OUTSTANDING and is Forest Road's to take
///      (CLAUDE.md §0.7).
interface IMintRedeemController {
    // ── Events ───────────────────────────────────────────────────────────
    event Minted(address indexed user, uint256 usdcIn, uint256 usdfrOut);
    event Redeemed(address indexed user, uint256 usdfrIn, uint256 usdcOut);
    /// @notice Emitted when USDfr is minted against attested yield receipts (waterfall path).
    event YieldMinted(address indexed to, uint256 amount);
    /// @notice Emitted when USDfr is burned to realize a loss (cascade layer 3).
    event LossBurned(address indexed from, uint256 amount);
    /// @notice AUDIT FIX (R16-M3). Emitted IN ADDITION to `Redeemed` when a redemption settled
    ///         below par because the protocol was under-backed. Carries the supply and backing
    ///         the quote was struck against, so the coverage ratio applied to any exit is
    ///         reconstructable purely from events (CLAUDE.md §3.1).
    /// @param user The redeemer.
    /// @param usdfrBurned USDfr burned (whole-USDC-unit aligned).
    /// @param usdcOut Native USDC units actually paid out.
    /// @param supply `totalUSDfr()` before the redemption.
    /// @param backing `backingValue()` before the redemption.
    event SubParRedemption(address indexed user, uint256 usdfrBurned, uint256 usdcOut, uint256 supply, uint256 backing);
    /// @notice AUDIT FIX (R17). Emitted alongside `SubParRedemption`. Records the value
    ///         PERMANENTLY crystallised out of the senior layer by an exit priced against a
    ///         REVERSIBLE impairment mark, and the running total. `mintableHeadroom()` nets the
    ///         running total out, so value recovered when the mark is released stays in the pool
    ///         as coverage instead of being minted to the `sUSDfr` vault as yield.
    /// @param user The redeemer who bore it.
    /// @param amount `usdfrBurned - usdcOut * 1e12` for this exit, in 18-decimal USD.
    /// @param cumulative `seniorSubParShortfall()` after this exit.
    event SeniorShortfallCrystallised(address indexed user, uint256 amount, uint256 cumulative);
    /// @notice AUDIT FIX (R16-M1). Governance authorized or revoked a `mintYield` destination.
    event YieldSinkUpdated(address indexed account, bool authorized);
    /// @notice AUDIT FIX (R16-M1/M2). Governance authorized or revoked a `burnLoss` source.
    event LossSourceUpdated(address indexed account, bool authorized);

    // ── Errors ───────────────────────────────────────────────────────────
    error Controller_NotKYCAllowed(address account);
    error Controller_BackingInvariantViolated(uint256 supply, uint256 backing);
    error Controller_ZeroAmount();
    error Controller_AmountTooSmall(uint256 usdfrAmount);

    /// @notice An unratified arm refused a direct redemption.
    /// @param armId Active custody arm.
    /// @param usdcOut Proposed settlement in native USDC units.
    /// @param usdfrIn USDfr claims proposed for redemption.
    error Controller_ReserveLossArmFreeze(uint256 armId, uint256 usdcOut, uint256 usdfrIn);

    /// @notice The redemption would have burned more USDfr than the post-draw supply.
    /// @dev CANTINA 3.1.1, RE-DERIVED AT SCALE 1 AND CLOSED RATHER THAN ACKNOWLEDGED. On Ethereum
    ///      the whole-unit grid returned `M mod 1e12` wei of headroom at the top of the range, so
    ///      `usdfrIn + drawn` overflowed only for inputs within 1e12 of `type(uint256).max` - a
    ///      panic window of width at most 2**40, which is why "acknowledged" was a defensible
    ///      judgement. At scale 1 the grid is the identity, `usdfrIn == usdfrAmount` exactly, and
    ///      the window widens to the whole top `drawn` of the range. That is not the same judgement
    ///      about the same object. Bounding the SUM rather than the addend makes the overflow
    ///      UNREPRESENTABLE rather than merely unlikely, refuses only inputs no holder can hold, and
    ///      makes `previewRedeem` answer a controller error instead of `Panic(0x11)`.
    /// @param usdfrIn The amount the exit would burn.
    /// @param bound `supply - drawn`, which `supply - drawn <= supply` makes underflow-free because
    ///        `drawn` was burned out of `supply`.
    error Controller_RedeemExceedsSupply(uint256 usdfrIn, uint256 bound);
    /// @notice AUDIT FIX (R4-01): the user par paths are closed while the reserve holds less USDC
    ///         than its idle ledger claims. Recognition of the gap is permissionless and immediate;
    ///         restoring custody, or the authenticated custody-loss cascade writing the ledger down
    ///         to the live balance, reopens mint and redeem with no governance action.
    /// @param shortfallValue The observable custody gap in 18-decimal USD.
    /// @param recognizedBacking Backing net of that gap — the honest basis.
    error Controller_ReserveCustodyShortfall(uint256 shortfallValue, uint256 recognizedBacking);

    /// @notice AUDIT FIX (R16-M3/M4/M5). The operation would have WIDENED an already-standing
    ///         backing deficit. Distinct from `Controller_BackingInvariantViolated`, which is
    ///         raised when a whole protocol would be pushed below par: an integrator seeing that
    ///         error inside a knowingly sub-par protocol would reasonably read it as the standing
    ///         condition rather than as a refusal of this specific call.
    /// @param deficitBefore `max(0, totalUSDfr() - backingValue())` before the operation.
    /// @param deficitAfter The same quantity after it, which must not exceed `deficitBefore`.
    error Controller_DeficitWorsened(uint256 deficitBefore, uint256 deficitAfter);

    /// @notice A paired-yield baseline is already open, so a second cannot be started.
    error Controller_PairedYieldAlreadyOpen(address caller);
    /// @notice A split mint must consume this caller's existing paired backing baseline.
    error Controller_PairedYieldRequired();
    /// @notice A paired operation cannot complete against a changed retention obligation.
    error Controller_PairedRetentionChanged(uint256 beforeRequirement, uint256 afterRequirement);
    /// @notice The protocol fee cannot exceed the total amount being issued.
    error Controller_InvalidYieldSplit(uint256 total, uint256 fee);

    /// @notice A paired-yield baseline was recorded before its caller moved backing.
    event PairedYieldOpened(address indexed caller, uint256 supplyBefore, uint256 backingBefore);

    /// @notice A stranded paired-yield baseline was cleared by governance.
    event PairedYieldCleared(address indexed caller);

    /// @notice Records the supply/backing baseline for a yield mint whose backing leg moves first.
    function beginPairedYield() external;

    /// @notice Governance escape for a paired-yield baseline stranded by a reverted operation.
    function clearStalePairedYield() external;

    /// @notice AUDIT FIX (R16-M3). Par issuance is closed while the protocol is under-backed for
    ///         ANY reason — a G3 conservative mark or a residual cascade deficit as well as the
    ///         R4-01 custody gap. `redeem` deliberately stays OPEN in this state and re-prices to
    ///         the coverage ratio; see `previewRedeem`.
    /// @param supply `totalUSDfr()` at the time of refusal.
    /// @param backing `backingValue()` at the time of refusal.
    error Controller_MintClosedWhileUnderBacked(uint256 supply, uint256 backing);

    /// @notice AUDIT FIX (R16-L2). The USDC the user was charged did not arrive in the reserve's
    ///         custody, or the reserve credited a value that does not match it. Measured from the
    ///         reserve's own token balance rather than from anything the reserve reports about
    ///         itself, so `mint` no longer derives both sides of its safety check from one module.
    /// @param requested Native USDC units pulled from the user.
    /// @param delivered The reserve's measured USDC balance increase.
    /// @param credited The 18-decimal value `depositUSDC` reported.
    error Controller_DepositNotCustodied(uint256 requested, uint256 delivered, uint256 credited);

    /// @notice AUDIT FIX (R16-M1). `to` is not a governance-authorized yield destination.
    error Controller_NotYieldSink(address to);

    /// @notice AUDIT FIX (R16-M1/M2). `from` is not a governance-authorized loss source. Without
    ///         this, `burnLoss` and `mintYield` composed into arbitrary confiscation, and
    ///         `USDfr.burn`'s allowance-free burn made any holder seizable one-sidedly.
    error Controller_NotLossSource(address from);

    /// @notice AUDIT FIX (R17). A loss source must be a CONTRACT. `burnLoss` burns with no
    ///         allowance, carries no backing assertion and is deliberately not pausable, so
    ///         listing an EOA would restore finding M2 — a forced, non-pro-rata seizure of one
    ///         named holder — in a single routine-looking timelock transaction. Mirrors
    ///         `ReserveManager.setLossAbsorber`/`setLossController`. Deliberately NOT applied to
    ///         `setYieldSink`, whose fee-recipient treasury may legitimately be an EOA.
    error Controller_LossSourceNotContract(address account);

    /// @notice AUDIT FIX (R17). The settled price was below the floor the caller named. The
    ///         one-argument `redeem` supplies the PAR floor, so it reverts with this rather than
    ///         silently haircutting a holder against a mark that may later be released.
    /// @param usdcOut What the redemption would have paid.
    /// @param minUsdcOut The floor the caller required.
    error Controller_SlippageExceeded(uint256 usdcOut, uint256 minUsdcOut);

    /// @notice AUDIT FIX (R17). Backing has fallen to zero, so there is nothing to pay out at any
    ///         size. Previously this answered `Controller_AmountTooSmall`, which told the holder
    ///         their amount was the problem when the truth was that the protocol was worth nothing.
    /// @param supply `totalUSDfr()` at the time of refusal.
    error Controller_NoRedeemableBacking(uint256 supply);

    /// @notice AUDIT FIX (R17). The USDC the redemption was priced at did not reach the redeemer.
    ///         The outflow twin of `Controller_DepositNotCustodied`: R16-L2 installed an
    ///         independent measurement on the inflow leg only, leaving `redeem` to take the
    ///         reserve's own word for a release on the leg where the holder's USDfr is already
    ///         burned and the loss is irreversible.
    /// @param expected The quoted payout in native USDC units.
    /// @param settled The redeemer's measured USDC balance increase.
    /// @param usdfrBurned The USDfr burned to pay for it.
    error Controller_RedemptionNotSettled(uint256 expected, uint256 settled, uint256 usdfrBurned);

    /// @notice AUDIT FIX (R17). USDC was left sitting on the controller after a mint. The
    ///         controller is value-neutral at rest; a reserve that funded the deposit from
    ///         somewhere other than the controller's allowance satisfies the delivery equality
    ///         while leaving the user's cash here with a live approval against it.
    /// @dev Measured as a DELTA across the call, never as an absolute balance: anyone can send
    ///      USDC to the controller, so `balanceOf(this) != 0` would be a one-wei permanent
    ///      griefing lock on `mint`.
    /// @param balanceBefore The controller's USDC balance before the deposit leg.
    /// @param balanceAfter Its balance after it. Any inequality is refused.
    error Controller_CashStrandedOnController(uint256 balanceBefore, uint256 balanceAfter);

    /// @notice AUDIT FIX (R17). The operation would have widened the deficit measured on the
    ///         RECOGNITION-AWARE basis — backing net of the custody shortfall the reserve can
    ///         observe right now. Raised only by `mintYield`, the one supply-EXPANDING path with
    ///         no custody precondition; `mint` and `redeem` are refused earlier by
    ///         `Controller_ReserveCustodyShortfall`, and `burnLoss` is deliberately ungated.
    /// @param deficitBefore `max(0, totalUSDfr() - recognizedBackingValue())` before the call.
    /// @param deficitAfter The same quantity after it.
    error Controller_RecognizedDeficitWorsened(uint256 deficitBefore, uint256 deficitAfter);

    /// @notice AUDIT FIX (R17). A yield mint would have consumed value retained against
    ///         `seniorSubParShortfall()` — the haircut crystallised out of holders who exited
    ///         against a REVERSIBLE impairment mark. `mintableHeadroom()` advertises the retention;
    ///         this error enforces it.
    /// @dev CORRECTED (SWEEP-1 MRC-F3, 2026-08-08). This sentence used to end "...because
    ///      `WaterfallEngine.fund`'s origination-fee mint is not sized off that headroom and would
    ///      otherwise spend it." THAT JUSTIFICATION EXPIRED AT R18. `WaterfallEngine.fund` now
    ///      reads `uint256 headroom = $.controller.mintableHeadroom();` and clamps
    ///      `mintable = fee <= headroom ? fee : headroom` (WaterfallEngine.sol:195-197);
    ///      `MintRedeemController` says so in two places, and
    ///      `test_R18_A1_originationSurvivesACrystallisedHaircut` passes over the clamped path.
    ///      This is the same class of defect the merge author fixed on
    ///      `CollateralRegistry.conservativeSeniorMark`: a stale justification on a value path is
    ///      a defect, because the next engineer prunes the guard once they discover the reason
    ///      given for it is untrue.
    ///
    ///      THE ERROR IS STILL LOAD-BEARING, ON A DIFFERENT GROUND — DO NOT DELETE IT. It is the
    ///      LAST line of defence rather than the only one. `CREDIT_ROLE` gates `mintYield`, and
    ///      `Deploy.s.sol` grants that role to `WaterfallEngine` alone TODAY; a second grantee, or
    ///      any future unclamped call site, would spend the junior retention silently. The clamp is
    ///      a caller-side property; this is the callee-side one.
    /// @param threshold THE BOUND THAT WAS ACTUALLY ENFORCED, which differs by branch and is why
    ///        this parameter is not named `retention`. On an ordinary yield mint it is
    ///        `seniorSubParShortfall()`, the junior retention the surplus must not fall below. On a
    ///        PAIRED mint opened by `beginPairedYield` it is the surplus recorded BEFORE the caller
    ///        moved any backing, because a paired move raises backing and supply by the identical
    ///        amount and the property enforced there is exact neutrality rather than a floor.
    ///        Reporting the retention on the paired branch made the error describe a rule that
    ///        branch does not apply; corrected 2026-09-10.
    /// @param surplus `max(0, recognizedBackingValue() - totalUSDfr())` after the mint.
    error Controller_SeniorRetentionBreached(uint256 threshold, uint256 surplus);

    /// @notice AUDIT FIX (R18). The reserve took the USDC and reported the right credit but did not
    ///         BOOK it as backing. The recognition twin of `Controller_DepositNotCustodied`: R16-L2
    ///         measured custody and R17 measured the reported credit, while recognition was left to
    ///         the NON-WORSENING deficit rule — which a standing surplus silently pays for, up to
    ///         its own size. Measured as a DELTA on `backingValue()` across the deposit leg, so no
    ///         surplus can absorb it, and as an EQUALITY, so an over-booking reserve is refused too.
    /// @param credited The 18-decimal value `depositUSDC` reported.
    /// @param recognized The measured increase in `backingValue()` across the same call.
    error Controller_DepositNotRecognized(uint256 credited, uint256 recognized);

    /// @notice AUDIT FIX (R18). A loss source must not be an EIP-7702 DELEGATED EOA. Since Pectra
    ///         an ordinary key-controlled wallet that signed a delegation carries a 23-byte
    ///         `0xef0100`-prefixed code field, so `EXTCODESIZE` returns 23 and
    ///         `Controller_LossSourceNotContract`'s check admitted it — leaving finding M2 (a
    ///         forced, allowance-free, non-pro-rata seizure of one named holder, unstoppable by the
    ///         guardian) one routine-looking timelock transaction away for exactly the class of
    ///         wallet the guard claimed to exclude.
    error Controller_LossSourceIsDelegatedEOA(address account);

    /// @notice AUDIT FIX (R18). A composite view was read while this contract's reentrancy guard
    ///         was entered — i.e. from inside a supply change that has not finished settling — and
    ///         would have answered a number known to be false.
    /// @dev `_redeem` burns before it releases, and `DefaultManager.realizeLoss` burns before it
    ///      writes backing down; `USDfr._update` fires the participation-points hook inside every
    ///      one of those burns. From there `mintableHeadroom()` read the entire realised loss of a
    ///      cascade as distributable yield capacity, `backingInvariantHolds()` read TRUE on a short
    ///      book and `previewRedeem` quoted PAR on it. Reverting is the honest answer and is
    ///      fail-closed for an integrator; returning the number is the R4-01 self-contradiction one
    ///      frame deeper. The raw delegating views (`backingValue`, `recognizedBackingValue`,
    ///      `totalUSDfr`) are NOT gated: each is true whenever it is read. Only the composites are.
    error Controller_ViewUnavailableMidTransition();

    /// @notice `redeem(uint256,uint256,uint256)` was included after the caller's deadline
    ///         (ADR-0034 W).
    error Controller_DeadlinePassed(uint256 deadline, uint256 nowTimestamp);
    /// @notice The junior-draw source named by `ReserveManager.lossAbsorber()` is not on the
    ///         governance-maintained `setLossSource` list (ADR-0034 Y-bis). Fail-closed: the exit
    ///         refuses rather than burning a third party's USDfr on an unvouched-for pointer.
    error Controller_ExitDrawSourceNotAuthorised(address source);
    /// @notice The junior-draw source reported one number and moved another, or delivered more
    ///         than was asked of it (ADR-0034 Y-bis). Measured, not trusted.
    error Controller_ExitDrawNotDelivered(uint256 requested, uint256 reported, uint256 measured);

    /// @notice Junior capital was drawn forward, in cascade order, to fund this exit's price
    ///         (ADR-0034 Y-bis). `drawn` USDfr was burned out of the junior layers.
    event SeniorExitJuniorDrawn(address indexed redeemer, uint256 required, uint256 drawn);

    // ── User paths (KYC-gated) ───────────────────────────────────────────
    /// @notice Deposits USDC (6 decimals) and mints USDfr 1:1 in 18-decimal USD units.
    function mint(uint256 usdcAmount) external returns (uint256 usdfrOut);

    /// @notice Burns USDfr and releases the reserve's cash equivalent AT PAR. While the protocol
    ///         is short this form settles at par out of JUNIOR capital drawn forward in the same
    ///         transaction (ADR-0034 Y-bis), and reverts `Controller_SlippageExceeded` only once
    ///         that draw cannot reach par. It never haircuts the caller. Use
    ///         `redeem(uint256,uint256)` to elect a sub-par exit.
    /// @dev AUDIT FIX (R18) CORRECTED THE NOTICE LINE ABOVE, which every block explorer, ABI
    ///      doc and integrator reads first. It said this form is "priced at the coverage ratio: par
    ///      while the protocol is whole, `backing / supply` while it is short". After R17's par
    ///      floor that is false of THIS form. The coverage-ratio behaviour described below is
    ///      R16-M3's and is true of the two-argument form.
    /// @dev CORRECTED AGAIN (SWEEP-1 MRC-F2, 2026-08-08) — SAME LINE, ONE ROUND LATER. R18's
    ///      replacement said this form "REVERTS" while short, full stop. That stopped being true
    ///      at ADR-0034 Y-bis, which draws curator first-loss and the sGROVE backstop forward in
    ///      the same transaction to fund the cascade-ordered price. MEASURED: with a gross quote of
    ///      185,928.705440 USDC this form settled 200,000.000000 — AT PAR, out of junior capital.
    ///      It reverts only when the draw cannot reach par. Two successive rounds put a false
    ///      settlement claim on the one line integrators read first; check it against
    ///      `MintRedeemController._quoteRedeem` and `_drawJuniorForExit` before editing it again.
    /// @dev AUDIT FIX (R17): THIS FORM SUPPLIES THE PAR FLOOR. It settles at par or reverts with
    ///      `Controller_SlippageExceeded`. R16 made the price a live function of state and left
    ///      this one-argument signature accepting whatever the ratio was at inclusion, while
    ///      several NON-timelocked paths move backing down in the same block. Taking a haircut is
    ///      now an explicit election: quote with `previewRedeem`, then call the two-argument form
    ///      with the floor you will accept.
    function redeem(uint256 usdfrAmount) external returns (uint256 usdcOut);

    /// @notice Burns USDfr and releases the reserve's cash equivalent, refusing to settle below
    ///         `minUsdcOut`. This is the form that accepts a SUB-PAR exit — an explicit, informed
    ///         election by the holder (R16-M3, R17).
    /// @dev CORRECTED (SWEEP-1 MRC-F2, 2026-08-08). This line said the form "pays the COVERAGE
    ///      RATIO". It pays the JUNIOR-DRAWN price, which is >= the coverage ratio and may be par:
    ///      ADR-0034 Y-bis draws curator first-loss and the sGROVE backstop forward in the same
    ///      transaction, and the gross `backing / supply` mark is only the floor the price degrades
    ///      to once junior capital is exhausted. Quote with `previewRedeem`, which shares the
    ///      drawn arithmetic.
    /// @dev AUDIT FIX (R17). `previewRedeem` is advisory ACROSS TRANSACTIONS — it shares
    ///      `redeem`'s arithmetic, not its state — so this parameter is the only thing that binds
    ///      the settlement price. Pass the value `previewRedeem` returned (or lower, to tolerate
    ///      movement).
    /// @dev THE DEADLINE IS NOW SHIPPED, ON A NEW SIGNATURE (ADR-0034 W). R17 wrote here that
    ///      "there is no deadline parameter: there is no AMM-style path here, and the floor alone
    ///      is sufficient to make the exit refusable", which argued an ACCEPTED requirement away.
    ///      `redeem(uint256,uint256,uint256)` carries it. THIS form is deliberately left
    ///      deadline-free rather than being given a new expiry semantic under an unchanged
    ///      signature — see that overload's NatSpec. Prefer the three-argument form.
    /// @param usdfrAmount USDfr offered; the burn is snapped down to the whole-USDC-unit grid.
    /// @param minUsdcOut The lowest native-USDC payout the caller will accept. Zero accepts ANY
    ///        price, including a deep haircut — pass zero only deliberately.
    function redeem(uint256 usdfrAmount, uint256 minUsdcOut) external returns (uint256 usdcOut);

    /// @notice Burns USDfr and releases the reserve's cash equivalent, refusing to settle below
    ///         `minUsdcOut` or after `deadline`. THE CANONICAL EXIT (ADR-0034 W).
    /// @dev A minimum-out bounds the PRICE; it does not bound WHEN the exit executes. Every path
