    ///      claimant's later USDfr→stable conversion.
    function availableLiquidity() public view returns (uint256) {
        QueueStorage storage $ = _storage();
        return Math.mulDiv($.reserves.idleReserve(), $.epochLiquidityBps, Config.BPS);
