// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.30;

import {IERC4626} from "@openzeppelin/contracts/interfaces/IERC4626.sol";

/// @title IsUSDfr
/// @notice The yield-bearing ERC-4626 vault over USDfr (ADR-0005). Yield accrues via the
///         assets/shares exchange rate; exits are routed through the epoch redemption
///         queue (ADR-0010) — the vault's instant withdraw/redeem paths are restricted
///         to the queue module.
interface IsUSDfr is IERC4626 {
    /// @notice Emitted when the redemption queue address is set.
    event RedemptionQueueUpdated(address indexed queue);

    /// @notice Instant exit attempted by an account other than the redemption queue.
    error SUSDfr_QueueOnly();
    /// @notice Share movement involving a sanctioned (blocked) party.
    error SUSDfr_TransferBlocked(address from, address to);
    /// @notice A management-fee rate above the permanent v1 cap was requested.
    error SUSDfr_ManagementFeeTooHigh(uint16 requestedBps);
    /// @notice A performance-fee rate above the permanent v1 cap was requested.
    error SUSDfr_PerformanceFeeTooHigh(uint16 requestedBps);
    /// @notice A fee checkpoint was attempted during a transient share update or
    ///         while a cross-module fee-accounting operation was locked.
    error SUSDfr_FeeAccrualReentrant();
    /// @notice A two-phase fee-accounting operation was completed by the wrong caller
    ///         or with the wrong operation type.
    error SUSDfr_InvalidFeeOperation(address caller, uint8 expectedKind, uint8 actualKind);
    /// @notice Share supply changed during a fee-neutral marked-NAV operation.
    error SUSDfr_FeeOperationSupplyChanged(uint256 expectedSupply, uint256 actualSupply);
    /// @notice A replacement fee recipient was not marked as a protocol-exempt address.
    error SUSDfr_FeeRecipientNotExempt(address recipient);
    /// @notice A proposed impairment source has no code or cannot return a uint256 impairment.
    error SUSDfr_InvalidImpairmentSource(address source);
    /// @notice A source reported less performance-fee impairment than redemption impairment.
    error SUSDfr_InvalidPerformanceFeeImpairment(uint256 pendingImpairment, uint256 performanceImpairment);
    /// @notice Emergency clearing was requested while the current impairment source is valid.
    error SUSDfr_ImpairmentSourceStillReadable(address source);
    /// @notice Emergency clearing was requested when no impairment source is configured.
    error SUSDfr_NoImpairmentSource();
    /// @notice Too little gas was supplied to prove source failure and finish recovery safely.
    error SUSDfr_InsufficientImpairmentRecoveryGas(uint256 available, uint256 required);
    /// @notice Emitted when the (fail-open) points hook reverted on a share move (P-04 telemetry).

    event PointsHookFailed(address indexed from, address indexed to, uint256 value);
    /// @notice Protocol fee shares were minted for time-based management fees.
    event ManagementFeeAccrued(uint256 elapsed, uint256 feeAssets, uint256 feeShares);
    /// @notice Protocol fee shares were minted on marked NAV above the global high-water mark.
    event PerformanceFeeAccrued(
        uint256 oldHighWaterMark, uint256 newHighWaterMark, uint256 profitAssets, uint256 feeAssets, uint256 feeShares
    );
    /// @notice A fee-neutral flow adjusted the global high-water mark.
    event HighWaterMarkAdjusted(uint256 oldHighWaterMark, uint256 newHighWaterMark);
    /// @notice An authorized module checkpointed fees and locked a junior-capacity operation.
    event FeeNeutralMarkedNavChangeStarted(address indexed module, uint256 supply);
    /// @notice The authorized junior-capacity operation released its checkpoint lock.
    event FeeNeutralMarkedNavChangeCompleted(address indexed module, uint256 supply);
    /// @notice The WaterfallEngine locked fee checkpoints before delivering senior yield.
    event YieldNotificationStarted(address indexed module);
    /// @notice Governance cleared a fee-operation lock left behind by a faulty trusted module.
    event FeeOperationEmergencyCleared(address indexed module, uint8 indexed operationKind);
    /// @notice The queue prepared one settlement chunk against the full remaining settlement
    ///         outflow bound before taking any price quote.
    /// @param maxAssets Maximum USDfr that the live settlement can still distribute.
    /// @param projectedHeld Physical USDfr that would remain if that full bound left the vault.
    /// @param instantlyRecognized Previously-unvested yield released before pricing.
    event RedemptionPricingPrepared(uint256 maxAssets, uint256 projectedHeld, uint256 instantlyRecognized);
    /// @notice Timelocked governance changed the prospective annual management-fee rate.
    event ManagementFeeSet(uint16 oldFeeBps, uint16 newFeeBps);
    /// @notice Timelocked governance changed the prospective global performance-fee rate.
    event PerformanceFeeSet(uint16 oldFeeBps, uint16 newFeeBps);
    /// @notice Timelocked governance changed the recipient of future vault fee shares.
    event VaultFeeRecipientSet(address indexed oldRecipient, address indexed newRecipient);
    /// @notice Timelocked governance cleared an unreadable impairment source without checkpointing it.
    /// @dev `failureHash` commits to the failed selector and bounded return evidence, or
    ///      to the semantically invalid pair of impairment values.
    event ImpairmentSourceEmergencyCleared(address indexed source, bytes32 failureHash);

    /// @notice Current fee-net realized exchange rate: assets per one whole sUSDfr token.
    /// @dev Simulates fee shares due at this timestamp even before a checkpoint transaction.
    function currentExchangeRate() external view returns (uint256);

    /// @notice Crystallizes management and global high-water-mark performance fees.
    /// @dev Permissionless. Fee shares mint to `feeRecipient`; no backing assets leave.
    /// @return managementShares Shares minted for the time-based management fee.
    /// @return performanceShares Shares minted for profit above the high-water mark.
    function accrueFees() external returns (uint256 managementShares, uint256 performanceShares);

    /// @notice Prepares queue redemption pricing against the live settlement's full remaining
    ///         outflow bound, then checkpoints fees once against the prepared state.
    /// @dev Queue-only. Using the settlement bound rather than the caller-selected request count
    ///      makes optional-stream recognition independent of keeper chunking (G4/M-2).
    /// @param maxAssets Maximum USDfr the settlement can still distribute.
    /// @return instantlyRecognized Previously-unvested yield released before pricing.
    function prepareRedemptionPricing(uint256 maxAssets) external returns (uint256 instantlyRecognized);

    /// @notice Checkpoints fees and locks checkpoints before an authorized junior-capacity change.
    /// @dev Must be paired atomically with `endFeeNeutralMarkedNavChange` by the same module.
    ///      Junior-capacity effects are excluded by the impairment source's independent
    ///      performance-fee view; this function never infers a capital flow from a NAV re-read.
    function beginFeeNeutralMarkedNavChange() external;

    /// @notice Releases an authorized junior-capacity operation's checkpoint lock.
    /// @dev The caller and share supply must match the opening snapshot.
    function endFeeNeutralMarkedNavChange() external;

    /// @notice Locks vault fee checkpoints before the WaterfallEngine delivers senior yield.
    /// @dev Must be paired atomically with `notifyYield` by the same module.
    function beginYieldNotification() external;

    /// @notice Clears a fee-operation lock that survived a successful trusted-module call.
    /// @dev Timelocked emergency recovery only. Correct module paths open and close their
    ///      lock atomically, so a persistent lock means the trusted caller is faulty.
    function clearStaleFeeOperation() external;

    /// @notice Current global performance-fee rate, in basis points of profit.
    function performanceFeeBps() external view returns (uint16);

    /// @notice Permanent v1 performance-fee ceiling, in basis points.
    function maxPerformanceFeeBps() external pure returns (uint16);

    /// @notice Current annualized management-fee rate, in basis points.
    function managementFeeBps() external view returns (uint16);

    /// @notice Permanent v1 management-fee ceiling, in basis points.
    function maxManagementFeeBps() external pure returns (uint16);

    /// @notice Time basis used to interpret the annual management-fee rate.
    function managementFeeYear() external pure returns (uint64);

    /// @notice Global post-fee high-water mark, in the same units as `feeExchangeRate`.
    function highWaterMark() external view returns (uint256);

    /// @notice Gross rate used for HWM accounting after fee-neutral junior-capital credit.
    /// @dev Unlike `currentExchangeRate`, this does not simulate pending fee shares. It can be
    ///      below the redemption-NAV rate while junior capital protects a live impairment.
    function feeExchangeRate() external view returns (uint256);

    /// @notice Recipient of sUSDfr management/performance fee shares.
    function feeRecipient() external view returns (address);

    /// @notice Last timestamp through which the management fee was accrued.
    function lastFeeAccrual() external view returns (uint64);

    /// @notice Sets the prospective management fee. Timelocked governance only.
    function setManagementFee(uint16 feeBps) external;

    /// @notice Sets the prospective performance fee. Timelocked governance only.
    function setPerformanceFee(uint16 feeBps) external;

    /// @notice Changes the recipient of future vault fee shares. Timelocked governance only.
    function setFeeRecipient(address recipient) external;

    /// @notice Clears a configured impairment source only when a bounded read demonstrably fails.
    /// @dev Timelocked governance recovery path. It deliberately cannot replace a readable source
    ///      or install a new source; normal changes must use the checkpointed setter. Any marked-NAV
    ///      lift is ratcheted fee-free, permanently waiving performance fees embedded in that lift.
    function clearUnreadableImpairmentSource() external;

    /// @notice Sets or clears the conservative marked-NAV impairment source.
    /// @dev Timelocked governance only. A non-zero replacement must pass an ABI read before
    ///      the old valuation period is checkpointed and the replacement is stored.
    function setImpairmentSource(address source) external;

    /// @notice Current conservative marked-NAV impairment source, or zero when unwired.
    function impairmentSource() external view returns (address);

    /// @notice The redemption queue module (sole permitted caller of withdraw/redeem).
    function redemptionQueue() external view returns (address);

    /// @notice Sets the redemption queue. Only DEFAULT_ADMIN_ROLE (timelocked governance).
    function setRedemptionQueue(address queue) external;

    /// @notice Recognizes realized senior yield immediately or starts optional vesting (ADR-0023).
    /// @dev Called by the WaterfallEngine right after it delivers `amount` USDfr into the
    ///      vault. Moves no value. With a zero vesting period, recognition and the resulting
    ///      performance-fee checkpoint complete in the caller's repayment transaction. A
    ///      non-zero governance setting defers recognition linearly as an optional
    ///      market-smoothing policy. Gated by CREDIT_ROLE.
    /// @param amount The realized yield just delivered into the vault.
    function notifyYield(uint256 amount) external;

    /// @notice Realized senior yield not yet released into the exchange rate (ADR-0023).
    function unvestedYield() external view returns (uint256);

    /// @notice The asset base exits price against: realized assets LESS the
    ///         declared-but-unrealized senior impairment (ADR-0022 Option Y).
    /// @dev Always `<= totalAssets()`, so redemption NAV <= deposit NAV.
    function redemptionTotalAssets() external view returns (uint256);

    /// @notice Shares that `assets` buys at the conservative redemption NAV, rounded DOWN.
    /// @dev The floor-rounded counterpart to `previewWithdraw` (which rounds up). The queue caps
    ///      its settlement budget with this so `previewRedeem(result) <= assets` holds by
    ///      construction and settlement can never distribute above the budget (CLAUDE.md §1.3).
    /// @param assets The budget, in USDfr.
    /// @return The largest share count whose conservative redemption value does not exceed `assets`.
    function convertToSharesAtRedemption(uint256 assets) external view returns (uint256);
}

src/interfaces/IReserveManager.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.30;

/// @title IReserveManager
/// @notice Mainnet-v1 treasury for canonical USDC and deployed facility principal.
/// @dev USD values use 18 decimals. USDC amounts use the token's native 6 decimals.
interface IReserveManager {
    /// @notice Canonical USDC was pulled into recorded idle custody.
    event USDCDeposited(address indexed from, uint256 requested, uint256 credited);
    /// @notice Canonical USDC was released from recorded idle custody.
    event USDCReleased(address indexed to, uint256 amount);
    /// @notice A permissionless observation compared recorded and live USDC custody.
    event IdleUSDCObserved(uint256 recorded, uint256 live, uint256 shortfall);
    /// @notice An adjudicated custody loss reduced recorded idle backing.
    event IdleUSDCWrittenDown(uint256 amount, uint256 remaining);
    /// @notice Returned USDC was credited against one arm's written-down recovery capacity.
    event RecoveredIdleUSDCCredited(
        uint256 indexed armId, uint256 nativeUnits, uint256 value, bytes32 indexed evidenceHash
    );
    /// @notice A custody loss reduced backing and fixed the supply reduction the cascade must absorb.
    event ReserveLossRecognized(
        uint256 indexed incidentId, uint256 backingReduction, uint256 surplusAbsorbed, uint256 supplyReductionRequired
    );
    /// @notice The complete surplus-to-senior allocation of one recognized custody loss.
    event ReserveLossAllocated(
        uint256 indexed incidentId,
        uint256 backingReduction,
        uint256 surplusAbsorbed,
        uint256 curatorAbsorbed,
        uint256 backstopCovered,
        uint256 seniorBurned,
        uint256 residualDeficit
    );
    /// @notice The controller used for supply, backing, and loss-burn checks changed.
    event LossControllerSet(address indexed previousController, address indexed newController);
    /// @notice The ordered custody-cascade and governance timing modules were wired.
    event ReserveLossModulesSet(
        address indexed curator, address indexed backstop, address indexed vault, address governor, address timelock
    );
    /// @notice A Guardian created a persistent reserve-loss interlock and evidence commitment.
    event ReserveLossArmed(uint256 indexed armId, uint256 indexed incidentId, bytes32 evidenceHash);
    /// @notice Governance cancelled an unused arm and disabled future Guardian arms.
    event ReserveLossArmCancelled(uint256 indexed armId, bytes32 indexed evidenceHash);
    /// @notice Governance closed the arm-bound incident and disabled future Guardian arms.
    event ReserveLossArmFinalized(uint256 indexed armId, uint256 indexed incidentId, bytes32 indexed evidenceHash);
    /// @notice Governance ratified and executed the current objective custody shortfall.
    event ReserveLossRatified(
        uint256 indexed armId,
        uint256 indexed incidentId,
        uint256 approvedMaxLoss,
        uint256 actualLoss,
        bytes32 evidenceHash
    );
    /// @notice Governance enabled or disabled creation of new Guardian reserve-loss arms.
    event GuardianReserveLossArmsEnabled(bool enabled);
    /// @notice A custody-loss incident entered the active register under its bound arm.
    event ReserveLossIncidentOpened(uint256 indexed incidentId, uint256 indexed armId, bytes32 evidenceHash);
    /// @notice The active custody-loss incident left the register.
    event ReserveLossIncidentClosed(uint256 indexed incidentId);
    /// @notice A cascade changed the latched unabsorbed reserve deficit.
    event ReserveDeficitUpdated(uint256 indexed incidentId, uint256 previousDeficit, uint256 currentDeficit);
    /// @notice Governance cleared a cured reserve-deficit latch with supporting evidence.
    event ReserveDeficitResolved(uint256 previousDeficit, bytes32 evidenceHash);
    /// @notice Idle USDC became deployed principal for a facility.
    event PrincipalDeployed(uint256 indexed facilityId, uint256 amount);
    /// @notice A retained origination fee became additional facility principal.
    event FeeCapitalized(uint256 indexed facilityId, uint256 amount);
    /// @notice A cash receipt increased idle custody and reduced the stated principal leg.
    event PaymentReceived(
        uint256 indexed facilityId, address indexed payer, uint256 usdcAmount, uint256 principalReturned
    );
    /// @notice Realized facility principal was removed from backing.
    event PrincipalWrittenDown(uint256 indexed facilityId, uint256 amount);
    /// @notice Governance added an evidence-backed conservative facility impairment.
    event PrincipalImpairmentRecognized(
        uint256 indexed facilityId,
        uint256 amount,
        uint256 facilityImpairment,
        uint256 totalImpairment,
        uint256 backingAfter,
        bytes32 evidenceHash
    );
    /// @notice Governance released part of an evidence-backed conservative facility impairment.
    event PrincipalImpairmentReleased(
        uint256 indexed facilityId,
        uint256 amount,
        uint256 facilityImpairment,
        uint256 totalImpairment,
        bytes32 evidenceHash
    );
    /// @notice A principal write-down consumed the corresponding previously recognized impairment.
    event PrincipalImpairmentRealized(
        uint256 indexed facilityId, uint256 amount, uint256 facilityImpairment, uint256 totalImpairment
    );
    /// @notice The retained compatibility loss-absorber binding changed.
    event LossAbsorberSet(address indexed previousAbsorber, address indexed newAbsorber);
    /// @notice A funder supplied new canonical USDC backing without minting claims.
    event Recapitalized(
        address indexed funder, uint256 units, uint256 credited, uint256 backingAfter, uint256 deficitOutstanding
    );
    /// @notice A senior-exit junior draw was added to the historical prepayment ledger.
    event ExitPrepaymentRecorded(uint256 amount, uint256 outstanding);
    /// @notice A facility loss consumed part of the historical exit-prepayment ledger.
    event ExitPrepaymentConsumed(uint256 indexed facilityId, uint256 consumed, uint256 outstanding);

    /// @notice Requested USDC value exceeds recorded idle value.
    error ReserveManager_InsufficientIdleValue(uint256 requestedValue, uint256 idleValue);
    /// @notice Requested principal reduction exceeds the facility's live deployed principal.
    error ReserveManager_InsufficientDeployedPrincipal(uint256 facilityId, uint256 requested, uint256 deployed);
    /// @notice A value-moving call supplied a zero amount.
    error ReserveManager_ZeroAmount();
    /// @notice A required account or module address is zero.
    error ReserveManager_ZeroAddress();
    /// @notice The caller is not an authorised controller or credit depositor.
    error ReserveManager_NotDepositor(address caller);
    /// @notice A pull expected canonical USDC but received no value.
    error ReserveManager_NoValueReceived();
    /// @notice The token balance delta differed from the requested USDC transfer.
    error ReserveManager_UnexpectedUSDCReceipt(uint256 expected, uint256 received);
    /// @notice A legacy idle write-down exceeds recorded idle value.
    error ReserveManager_WriteDownExceedsIdle(uint256 amount, uint256 idle);
    /// @notice A USDC release or deployment attempted to target the ReserveManager itself.
    error ReserveManager_SelfDeployment();
    /// @notice An 18-decimal value cannot be represented exactly in native USDC units.
    error ReserveManager_ValueNotUSDCExact(uint256 value);
    /// @notice The configured custody token does not use canonical USDC's six decimals.
    error ReserveManager_InvalidUSDCDecimals(uint8 decimals);
    /// @notice A payment allocated more principal than the USDC value actually received.
    error ReserveManager_PrincipalExceedsPayment(uint256 principal, uint256 paymentValue);
    /// @notice A proposed curator, backstop, vault, or absorber fails its binding contract.
    error ReserveManager_InvalidLossAbsorber(address absorber);
    /// @notice A proposed controller fails its module and reserve binding contract.
    error ReserveManager_InvalidLossController(address controller);
    /// @notice A loss layer's reported burn differs from the observed USDfr supply reduction.
    error ReserveManager_LossAbsorberContractViolated(uint256 backingReduction, uint256 supplyBurned);
    /// @notice Reported cascade allocation does not reconcile to the recognized loss.
    error ReserveManager_LossAllocationMismatch(
        uint256 expectedSurplus, uint256 reportedSurplus, uint256 expectedAccounted, uint256 reportedAccounted
    );
    /// @notice The terminal live supply/backing deficit differs from the cascade calculation.
    error ReserveManager_PostLossDeficitMismatch(uint256 expectedDeficit, uint256 observedDeficit);
    /// @notice A custody incident id has already been consumed.
    error ReserveManager_IncidentAlreadyUsed(uint256 incidentId);
    /// @notice A new arm or incident cannot replace the currently active incident.
    error ReserveManager_IncidentAlreadyActive(uint256 incidentId);
    /// @notice A terminal action requires an active custody incident.
    error ReserveManager_NoActiveIncident();
    /// @notice The supplied custody incident does not match the active incident.
    error ReserveManager_IncidentMismatch(uint256 expected, uint256 supplied);
    /// @notice The caller lacks the reserve-administration authority required for the live loss path.
    error ReserveManager_ReserveLossCallerNotAdmin(address caller);
    /// @notice A reserve-loss allocation used an id outside the custody-event namespace.
    error ReserveManager_InvalidReserveLossIncident(uint256 incidentId);
    /// @notice A cascade was requested without a recognized supply reduction.
    error ReserveManager_NoRecognizedReserveLoss();
    /// @notice Finalization was attempted while recognized loss remains unallocated.
    error ReserveManager_RecognizedLossOutstanding(uint256 amount);
    /// @notice Finalization was attempted while live USDC custody remains short.
    error ReserveManager_LiveShortfallExists(uint256 nativeUnits);
    /// @notice Finalization was attempted while supply still exceeds backing.
    error ReserveManager_DeficitStillExists(uint256 recordedDeficit, uint256 observedDeficit);
    /// @notice Creation of new Guardian reserve-loss arms is disabled.
    error ReserveManager_GuardianArmsDisabled();
    /// @notice A new arm cannot replace the currently active arm.
    error ReserveManager_ArmAlreadyActive(uint256 armId);
    /// @notice An arm-bound action requires an active arm.
    error ReserveManager_NoActiveArm();
    /// @notice The supplied arm id does not match the active arm.
    error ReserveManager_ArmMismatch(uint256 expected, uint256 supplied);
    /// @notice Ratification evidence does not match the Guardian's armed commitment.
    error ReserveManager_ArmEvidenceMismatch(bytes32 expected, bytes32 supplied);
    /// @notice The monotonic arm id space is exhausted.
    error ReserveManager_ArmIdExhausted();
    /// @notice Ratification found that the objective custody shortfall was already cured.
    error ReserveManager_ShortfallCured();
    /// @notice The live custody loss exceeds governance's approved maximum.
    error ReserveManager_LossExceedsApproval(uint256 actualLoss, uint256 approvedMaxLoss);
    /// @notice No physically returned USDC is available for the supplied arm.
    error ReserveManager_NoRecoveredUSDC(uint256 armId);
    /// @notice Finalization found returned USDC that has not yet been credited.
    error ReserveManager_RecoveredUSDCNotCredited(uint256 armId, uint256 nativeUnits);
    /// @notice The superseded arbitrary idle-write-down entry is permanently disabled.
    error ReserveManager_LegacyPathDisabled();
    /// @notice Cancellation would release an interlock while a loss condition remains live.
    error ReserveManager_InterlockReleaseForbidden();
    /// @notice Loss-module rebinding is forbidden while an arm, incident, shortfall, or deficit is live.
    error ReserveManager_ModuleRebindForbidden();
    /// @notice The proposed governor and timelock do not expose one coherent live timing path.
    error ReserveManager_InvalidGovernanceTiming(address governor, address timelock);
    /// @notice An evidence-backed transition supplied the zero evidence hash.
    error ReserveManager_ZeroEvidenceHash();
    /// @notice A conservative impairment would exceed the facility's remaining face principal.
    error ReserveManager_ImpairmentExceedsFace(uint256 facilityId, uint256 requested, uint256 remainingFace);
    /// @notice An impairment release exceeds the amount currently recognized for the facility.
    error ReserveManager_ImpairmentReleaseExceedsRecognized(uint256 facilityId, uint256 requested, uint256 recognized);
    /// @notice The caller is not the retained compatibility loss absorber.
    error ReserveManager_NotLossAbsorber(address caller);
    /// @notice Recorded idle USDC exceeds live custody, so a protected out-door is closed.
    error ReserveManager_IdleCustodyShortfall(uint256 recordedUnits, uint256 liveUnits);
    /// @notice A legacy incident nonce is zero or enters the reserved custody namespace.
    error ReserveManager_InvalidIncidentNonce(uint256 incidentNonce);
    /// @notice Deficit resolution was requested without a recorded deficit.
    error ReserveManager_NoReserveDeficit();
    /// @notice An incident close requires its recorded deficit to be resolved first.
    error ReserveManager_DeficitResolutionRequired(uint256 recordedDeficit);

    /// @notice Pulls exact canonical USDC from `from` into recorded idle custody.
    function depositUSDC(address from, uint256 amount) external returns (uint256 credited);
    /// @notice Releases recorded idle USDC through the controller-only redemption path.
    function releaseUSDC(address to, uint256 amount) external;

    /// @notice Permissionlessly checkpoints the objective live-vs-recorded custody shortfall.
    /// @dev Observation never changes backing and never moves junior or senior capital.
    /// @return shortfall Native six-decimal USDC units missing from custody.
    function reconcileIdleUSDC() external returns (uint256 shortfall);

    /// @notice Permissionless live-vs-recorded custody observation; never changes accounting.
    function observeIdleUSDC() external view returns (uint256 recorded, uint256 live, uint256 shortfall);

    /// @notice Native USDC units by which recorded idle custody exceeds the live token balance.
    function idleCustodyShortfall() external view returns (uint256);
    /// @notice Recorded backing net of any physically observable idle-custody shortfall.
    function recognizedBackingValue() external view returns (uint256);
    /// @notice Whether an arm, incident, recognized loss, deficit, or live shortfall locks exits.
    function custodyLossUnabsorbed() external view returns (bool);

    /// @notice Wires the controller used for direct supply/backing and loss-burn checks.
    function setLossController(address controller) external;
    /// @notice Wires the retained compatibility absorber after verifying its reserve binding.
    function setLossAbsorber(address absorber) external;

    /// @notice Legacy incident controls retained as non-credit compatibility surfaces while
    ///         new custody accounting uses the arm-bound ratification path.
    function openReserveLossIncident(uint256 incidentNonce, bytes32 evidenceHash)
        external
        returns (uint256 incidentId);
    /// @notice Closes the exact active legacy incident once no deficit remains.
    function closeReserveLossIncident(uint256 incidentId) external;
    /// @notice Clears a cured legacy reserve-deficit latch with supporting evidence.
    function resolveReserveDeficit(bytes32 evidenceHash) external;
    /// @notice Canonical USDC held above the amount recorded as idle custody.
    function unrecordedUSDC() external view returns (uint256);

    /// @notice Wires the ordered custody cascade and its live governance timing sources.
    function setReserveLossModules(address curator, address backstop, address vault, address governor, address timelock)
        external;

    /// @notice Guardian-only persistent interlock created before an amount-bearing proposal.
    /// @return armId Monotonic internal id consumed only by an explicit governance terminal action.
    /// @return incidentId Structurally bound upper-half custody event id.
    function armReserveLossFreeze(bytes32 evidenceHash) external returns (uint256 armId, uint256 incidentId);

    /// @notice Governance consumes an unused arm only when the objective shortfall is zero and
    ///         no adjudicated loss, incident or deficit exists; future Guardian arms stay disabled.
    function cancelAndDisable(uint256 expectedArmId, bytes32 evidenceHash) external;

    /// @notice Governance kill switch for repeated Guardian arms.
    function setGuardianReserveLossArmsEnabled(bool enabled) external;

    /// @notice Governance ratifies and atomically absorbs the live objective shortfall, bounded
    ///         by the amount approved in the proposal. Every tranche under an arm reuses its id
    ///         and must supply the Guardian's exact armed evidence commitment.
    function ratifyAndOpen(uint256 expectedArmId, bytes32 evidenceHash, uint256 approvedMaxLoss)
        external
        returns (uint256 incidentId, uint256 actualLoss);

    /// @notice Credits physically returned canonical USDC without minting USDfr, capped by the
    ///         amount previously written down under `armId`. May execute after incident closure.
    function creditRecoveredIdleUSDC(uint256 armId, bytes32 evidenceHash) external returns (uint256 credited);

    /// @notice Atomically resolves a cured deficit, closes the arm-bound incident and disables
    ///         future Guardian arms. It cannot release a shortfall or uncredited returned USDC.
    function finalizeAndDisable(uint256 expectedArmId, bytes32 evidenceHash) external;

    /// @notice Pulls new canonical USDC backing without minting USDfr claims.
    function recapitalize(uint256 amount) external returns (uint256 credited);

    /// @notice Controller used for supply, backing, and loss-burn verification.
    function lossController() external view returns (address);
    /// @notice Ordered curator, backstop, vault, governor, and timelock bindings.
    function reserveLossModules()
        external
        view
        returns (address curator, address backstop, address vault, address governor, address timelock);
    /// @notice Active custody incident id and its evidence commitment.
    function activeReserveLossIncident() external view returns (uint256 incidentId, bytes32 evidenceHash);
    /// @notice Whether a custody incident id has already entered the durable register.
    function reserveLossIncidentUsed(uint256 incidentId) external view returns (bool);
    /// @notice Latched portion of adjudicated custody losses not absorbed by any capital layer.
    function reserveDeficit() external view returns (uint256);
    /// @notice Current recognized backing reduction and pending cascade requirement.
    function recognizedReserveLoss()
        external
        view
        returns (uint256 backingReduction, uint256 surplusAbsorbed, uint256 supplyReductionRequired);
    /// @notice Active arm identity, derived incident, armed evidence, and future-arm switch.
    function reserveLossArm()
        external
        view
        returns (uint256 armId, uint256 incidentId, bytes32 evidenceHash, bool armsEnabled);
    /// @notice Native USDC recovery capacity created by write-downs under one arm.
    function reserveLossRecoveryCapacity(uint256 armId) external view returns (uint256 nativeUnits);
    /// @notice Retained compatibility absorber bound to this reserve.
    function lossAbsorber() external view returns (address);
    /// @notice Historical junior prepayment still available for impairment release.
    function exitPrepaidAbsorption() external view returns (uint256);
    /// @notice Records a senior-exit junior draw in the compatibility prepayment ledger.
    function recordExitPrepayment(uint256 amount) external;
    /// @notice Consumes prepayment only against recognized impairment for a facility loss.
    function consumeExitPrepayment(uint256 facilityId, uint256 loss) external returns (uint256 used);

    /// @notice Shared fail-closed interlock consumed by curator withdrawals and queue settlement.
    function reserveLossExitsLocked() external view returns (bool);

    /// @notice Backwards-compatible semantic alias used by CuratorModule.
    function curatorWithdrawalsLocked() external view returns (bool);

    /// @notice Converts exact recorded idle USDC into deployed facility principal.
    function recordDeployment(uint256 facilityId, address to, uint256 usdcAmount) external;
    /// @notice Adds retained origination-fee cash as facility principal without moving custody.
    function recordFeeCapitalization(uint256 facilityId, uint256 amount) external;

    /// @notice Atomically pulls exact USDC and accounts the principal leg.
    function recordPayment(uint256 facilityId, address payer, uint256 usdcAmount, uint256 principal)
        external
        returns (uint256 receivedValue);

    /// @notice Removes realized facility principal and consumes its corresponding impairment.
    function recordPrincipalWritedown(uint256 facilityId, uint256 amount) external;

    /// @notice Records an evidence-backed conservative mark without moving face principal or
    ///         allocating the loss between capital layers.
    function recognizePrincipalImpairment(uint256 facilityId, uint256 amount, bytes32 evidenceHash) external;

    /// @notice Reverses a conservative mark, bounded by the amount previously recognized.
    function releasePrincipalImpairment(uint256 facilityId, uint256 amount, bytes32 evidenceHash) external;

    /// @notice Recorded idle custody expressed as 18-decimal USDfr value.
    function idleReserve() external view returns (uint256);
    /// @notice Recorded idle custody in native six-decimal USDC units.
    function idleUSDC() external view returns (uint256);
    /// @notice Aggregate deployed facility principal before conservative impairments.
    function deployedPrincipal() external view returns (uint256);
    /// @notice Aggregate evidence-backed conservative principal impairment.
    function totalPrincipalImpairment() external view returns (uint256);
    /// @notice Evidence-backed conservative impairment recorded for one facility.
    function principalImpairmentOf(uint256 facilityId) external view returns (uint256);
    /// @notice Recorded idle plus deployed principal, net of conservative impairments.
    function totalBackingValue() external view returns (uint256);
    /// @notice Remaining face principal deployed to one facility.
    function deployedTo(uint256 facilityId) external view returns (uint256);
    /// @notice Canonical six-decimal USDC token held by the reserve.
    function usdc() external view returns (address);
    /// @notice Converts native six-decimal USDC units to 18-decimal protocol value.
    function normalizeUSDC(uint256 amount) external pure returns (uint256);
    /// @notice Converts exact 18-decimal protocol value to native USDC units.
    function denormalizeUSDC(uint256 value) external pure returns (uint256);
}

src/interfaces/IRedemptionQueue.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.30;

/// @title IRedemptionQueue — epoch FIFO exits for sUSDfr (ADR-0010, the QEV analog)
/// @notice The vault's ONLY exit path: capital sits in illiquid amortizing facilities,
///         so sUSDfr redemptions queue and settle at epoch close, strictly FIFO, from
///         a liquidity budget snapshotted per settlement. The §1.3 queue invariants —
///         never distribute more than available liquidity, FIFO holds, no
///         double-claim — are this module's safety spec.
interface IRedemptionQueue {
    // ── Events ───────────────────────────────────────────────────────────
    event RedemptionRequested(uint256 indexed requestId, address indexed owner, uint256 shares, uint256 epoch);
    /// @notice A (possibly partial) fill at settlement: `shares` burned for `assets`.
    event RequestFilled(uint256 indexed requestId, uint256 shares, uint256 assets, uint256 epoch);
    event Claimed(uint256 indexed requestId, address indexed owner, uint256 assets);
    /// @notice A settlement finished and the next epoch opened.
    /// @dev AUDIT NOTE (Q-01 round 4): `distributed` MAY now fall below `minRedemptionValue` on a
    ///      committed settlement, by at most `MIN_RESIDUE_VALUE` (1e-6 USDfr). Before the Q-01
    ///      fix, `!drained && committed` implied `distributed >= minRedemptionValue` by
    ///      construction and was checkable from this event alone. It no longer is. Pair this
    ///      event with `SettlementWithheld` to recompute the abandon predicate off-chain.
    event EpochClosed(uint256 indexed epoch, uint256 budget, uint256 distributed, uint64 nextEpochEndsAt);
    /// @notice Value the Q-01 residue guard deliberately withheld from a settlement, so that a
    ///         partial fill could not leave the head with a residue inside the zero-value window.
    /// @dev Emitted only when the guard actually reduces a fill. The abandon guard credits this
    ///      value back, so the on-chain commit test is
    ///      `settlementDistributed + withheld >= settlementMinValue`. Without this event that
    ///      predicate is not reconstructable from the log (CLAUDE.md §3.1), because `withheld` is
    ///      a stack local that never reaches storage.
    /// @param epoch The settlement's epoch.
    /// @param requestId The head request the value was withheld from.
    /// @param value Withheld USDfr value, strictly below `MIN_RESIDUE_VALUE`.
    event SettlementWithheld(uint256 indexed epoch, uint256 indexed requestId, uint256 value);
    /// @notice One transaction-sized pricing session settled through one aggregate vault burn.
    /// @dev `pricingAssets + 1` over `pricingSupply + 10**vault.decimalsOffset()` is the single
    ///      canonical rate used for selection; the final request receives deterministic floor dust.
    event PricingBatchSettled(
        uint256 indexed epoch,
        uint256 indexed sessionId,
        uint256 firstRequestId,
        uint256 lastRequestId,
        uint256 pricingAssets,
        uint256 pricingSupply,
        uint256 aggregateShares,
        uint256 assetsReceived,
        bytes32 pricingStateHash
    );
    event EpochDurationSet(uint64 duration);
    event EpochLiquidityBpsSet(uint16 bps);
    /// @notice The forced per-request redemption cooldown was set (ADR-0022).
    event RedeemCooldownSet(uint64 cooldown);
    /// @notice The C-1 anti-dust-wedge minimum redemption value was set.
    event MinRedemptionValueSet(uint256 value);

    // ── Errors ───────────────────────────────────────────────────────────
    error Queue_ZeroAddress();
    error Queue_ZeroAmount();
    error Queue_EpochNotOver(uint64 endsAt);
    error Queue_NotSettling();
    error Queue_UnknownRequest(uint256 requestId);
    error Queue_NotRequestOwner(uint256 requestId, address caller);
    error Queue_NothingClaimable(uint256 requestId);
    error Queue_BadParams();
    /// @notice A settlement could distribute nothing while requests are queued: it snapshotted
    ///         zero distributable liquidity, or the remaining budget could not buy a nonzero
    ///         slice of the head (C-1, the dust-tail case). The epoch is NOT consumed and no
    ///         position is burned; retry when liquidity returns.
    ///         Contrast `Queue_HeadNotRedeemable`, which is a VALUATION block, not a cash one.
    error Queue_NoLiquidity();
    /// @notice C-1 remediation. The settlement front cannot be redeemed for any nonzero amount
    ///         at the conservative redemption NAV (ADR-0022) — a declared senior impairment has
    ///         marked the queued book down below a wei, so there is nothing to pay ANY holder.
    ///         Settlement stops LOUDLY rather than stalling silently: the epoch is not consumed,
    ///         no position is burned, and every request keeps its shares and its place. It clears
    ///         when the mark is cured or realized. `headValuation()` reports the state off-chain.
    ///         The `minRedemptionValue` entry floor bars a dust head from arising except under a
    ///         near-total senior loss, so under normal operation this block coincides with the
    ///         whole senior layer being marked below a wei, not one dust position blocking solvent
    ///         ones behind it.
    /// @param requestId The head request settlement stopped at.
    /// @param sharesRemaining Its unfilled shares, untouched.
    error Queue_HeadNotRedeemable(uint256 requestId, uint256 sharesRemaining);
    /// @notice Every queued request is still within its forced cooldown (ADR-0022) — the
    ///         heartbeat is NOT consumed; `eligibleAt` is when the head becomes settleable.
    error Queue_AllInCooldown(uint256 eligibleAt);
    /// @notice The request is worth less than `minRedemptionValue` at the realized rate — rejected
    ///         (C-1 anti-dust-wedge floor + N-1 anti-griefing). `value` is its realized worth.
    error Queue_BelowMinRedemption(uint256 value, uint256 minimum);
    /// @notice C-01 shared exit interlock: an objective custody shortfall, persistent arm,
    ///         adjudicated incident, unabsorbed loss or deficit prevents new senior settlement.
    error Queue_ReserveLossSettlementFrozen();
    error Queue_PricingQuoteChanged(uint256 quotedAssets, uint256 receivedAssets);
    error Queue_PricingBudgetExceeded(uint256 quotedAssets, uint256 remainingBudget);
    error Queue_PricingAllocationMismatch(uint256 receivedAssets, uint256 allocatedAssets);
    error Queue_PricingRangeInvalid(uint256 expectedRequestId, uint256 actualRequestId);
    error Queue_PricingSessionExhausted();

    // ── User paths ───────────────────────────────────────────────────────
    /// @notice Queues `shares` for redemption (transfers them into queue custody —
    ///         accrual-bearing participation ends here; see the ADR-0016 note in the
    ///         implementation). Strict FIFO position; no cancellation (queue-jump
    ///         gaming is not worth the surface in v1 — ADR-0010). Strict FIFO with no
    ///         reordering. Reverts `Queue_BelowMinRedemption` if the request is worth less than
    ///         `minRedemptionValue` (default $1) at the realized rate — the C-1 anti-dust-wedge
    ///         floor. A head worth < 1 wei at the conservative mark is never burned and never
    ///         requeued; settlement stops loudly (`Queue_HeadNotRedeemable`) until the mark cures.
    ///         No cancellation, so ADR-0018 stands.
    function requestRedeem(uint256 shares) external returns (uint256 requestId);

    /// @notice Transfers the filled USDfr of `requestId` to its owner. Callable by the
    ///         owner only, any time after (partial) fill; zeroes the claimable amount.
    function claim(uint256 requestId) external returns (uint256 assets);

    // ── Settlement (KEEPER-GATED — budget rules enforce safety) ──────────
    /// @notice Settles the epoch once its end has passed: snapshots the liquidity
    ///         budget on first call, then fills requests strictly FIFO (head request
    ///         may fill partially) until the budget, the queue, or `maxRequests` is
    ///         exhausted. Call repeatedly to process a long queue; the epoch advances
    ///         when settlement completes.
    ///         C-1: a fill is NEVER taken at a price of zero. If the head's whole remainder
    ///         prices to zero (senior front not redeemable at the conservative mark), settlement
    ///         stops with `Queue_HeadNotRedeemable` without consuming the epoch or burning
    ///         anything; the head keeps its FIFO place and settles when the mark cures.
    /// @dev    Requires `SETTLEMENT_KEEPER_ROLE`; reverts `AccessControlUnauthorizedAccount`
    ///         otherwise, and does so BEFORE the pause check. Gated because the epoch liquidity
    ///         budget is a spot read taken inside this call, which made it flash-loan
    ///         manipulable while permissionless (D7-01). Supersedes ADR-0018 §2.
    function closeEpoch(uint256 maxRequests) external;

    // ── Governance ───────────────────────────────────────────────────────
    /// @notice Sets the epoch cadence. Timelocked governance only.
    function setEpochDuration(uint64 duration) external;

    /// @notice Sets the share of stable liquidity distributable per settlement.
    function setEpochLiquidityBps(uint16 bps) external;

    /// @notice Sets the forced per-request redemption cooldown (ADR-0022). Timelocked
    ///         governance only. Applies uniformly to in-flight requests.
    function setRedeemCooldown(uint64 cooldown) external;

    /// @notice Sets the C-1 anti-dust-wedge minimum redemption value (realized USDfr).
    ///         Timelocked governance only; capped so it can never lock ordinary redeemers out.
    function setMinRedemptionValue(uint256 value) external;

    // ── Views ────────────────────────────────────────────────────────────
    /// @notice Current epoch number (starts at 1).
    function currentEpoch() external view returns (uint256);

    /// @notice When the current epoch can settle.
    function epochEndsAt() external view returns (uint64);

    /// @notice True while a settlement is in progress (between first and last
    ///         `closeEpoch` chunk).
    function isSettling() external view returns (bool);

    /// @notice The liquidity budget remaining in the active settlement (0 when idle).
    function settlementBudgetRemaining() external view returns (uint256);

    /// @notice Number of completed transaction-sized pricing sessions.
    /// @dev Monotone across epoch boundaries; lets monitoring distinguish a deliberate price
    ///      revision boundary from two prices inside one session.
    function pricingSessionCount() external view returns (uint256);

    /// @notice What a settlement starting now could distribute: the governance-set
    ///         share of the treasury's idle canonical-USDC liquidity.
    function availableLiquidity() external view returns (uint256);

    /// @notice The forced per-request redemption cooldown, in seconds (ADR-0022).
    function redeemCooldown() external view returns (uint64);

    /// @notice The C-1 anti-dust-wedge minimum redemption value, in realized USDfr (default $1).
    function minRedemptionValue() external view returns (uint256);

    /// @notice The earliest timestamp at which `requestId` may be settled by `closeEpoch`
    ///         (its `requestedAt + redeemCooldown`).
    function eligibleToSettleAt(uint256 requestId) external view returns (uint256);

    /// @notice A request's state.
    /// @return owner The requester.
    /// @return sharesRemaining Shares still queued (not yet filled).
    /// @return assetsClaimable Filled USDfr not yet claimed.
    /// @return epochRequested The epoch the request joined.
    /// @return requestedAt The timestamp the request was made (the cooldown clock, ADR-0022).
